(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-071"]={"sura":71,"name_ar":"نوح","name_en":"Nuh","verses":28,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":28,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=4\" class=\"link\">71:4</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:4 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=4\" class=\"link\">71:4</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:4 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=4\" class=\"link\">71:4</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:4 ஐ பார்க்கவும்"},"4":{"html":"<strong>இது மக்காவில் அருளப்பட்டது  (வசனங்கள்: 28) </strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.)<br />\r\n<br />\r\n<strong>நூஹ் (அலை) அவர்கள் தம் மக்களுக்கு விடுத்த அழைப்பு</strong><br />\r\n<br />\r\nநூஹ் (அலை) அவர்களைப் பற்றி அல்லாஹ் கூறுகிறான்: அவர்களுக்கு வேதனை வருவதற்கு முன்பே அல்லாஹ்வின் தண்டனையைக் குறித்து அவர்களை எச்சரிக்குமாறு கட்டளையிட்டு, அவர்களை அவர்களின் சமூகத்தாரிடம் அல்லாஹ் அனுப்பினான். அவர்கள் மனம் வருந்தி (தவ்பா செய்து) அல்லாஹ்வின் பக்கம் திரும்பினால், அந்தத் தண்டனை அவர்களை விட்டு நீக்கப்படும் என்று அவர்கள் தம் மக்களிடம் கூற வேண்டியிருந்தது. இதற்காகவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّا</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">نُوحًا</span> <span class=\"quran-arabic-font text-success\">إِلَىٰ</span> <span class=\"quran-arabic-font text-success\">قَوْمِهِ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَنذِرْ</span> <span class=\"quran-arabic-font text-success\">قَوْمَكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَأْتِيَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">أَلِيمٌ</span> * <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">قَوْمِ</span> <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">نَذِيرٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ﴿</span><br />\r\n<br />\r\n(\"உமது சமூகத்தாருக்குத் துன்புறுத்தும் வேதனை வருவதற்கு முன்னதாக, நீர் அவர்களை எச்சரிக்கை செய்வீராக\" (என்று நாம் கட்டளையிட்டோம்). அதற்கு அவர்கள் கூறினார்கள்: \"என் சமூகத்தாரே! நிச்சயமாக நான் உங்களுக்குத் தெளிவாக எச்சரிக்கை செய்பவன்.\") அதாவது, எச்சரிக்கையைத் தெளிவுபடுத்துதல் மற்றும் விஷயத்தை வெளிப்படையாகவும் தெளிவாகவும் விளக்குதல் ஆகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَنِ</span> <span class=\"quran-arabic-font text-success\">اعْبُدُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَاتَّقُوهُ﴿</span><br />\r\n<br />\r\n(நீங்கள் அல்லாஹ்வையே வணங்குங்கள்; அவனுக்கு அஞ்சி (தக்வாவுடன்) நடந்து கொள்ளுங்கள்,) அதாவது, 'அவன் தடை செய்தவற்றை விட்டுவிடுங்கள், அவன் பாவம் என்று அறிவித்தவற்றைத் தவிர்த்து விடுங்கள்' என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَطِيعُونِ﴿</span><br />\r\n<br />\r\n(மேலும், எனக்குக் கீழ்ப்படியுங்கள்,) 'நான் உங்களுக்குக் கட்டளையிடுபவற்றிலும், உங்களைத் தடுப்பவற்றிலும் எனக்குக் கட்டுப்படுங்கள்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لَكُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ذُنُوبِكُمْ﴿</span><br />\r\n<br />\r\n(அவன் உங்கள் பாவங்களை மன்னிப்பான்) அதாவது, 'நான் உங்களுக்குக் கட்டளையிட்டதை நீங்கள் செய்து, எச் செய்தியுடன் நான் உங்களிடம் அனுப்பப்பட்டேனோ அதை நீங்கள் விசுவாசித்தால் (ஈமான் கொண்டால்), அல்லாஹ் உங்கள் பாவங்களை மன்னிப்பான்' என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَيُؤَخِّرْكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَىٰ</span> <span class=\"quran-arabic-font text-success\">أَجَلٍ</span> <span class=\"quran-arabic-font text-success\">مُّسَمًّى﴿</span><br />\r\n<br />\r\n(மேலும், ஒரு குறிப்பிட்ட காலம் வரை உங்களுக்கு அவகாசம் அளிப்பான்.) அதாவது, 'அவன் உங்கள் ஆயுளை நீட்டிப்பான்; அவனுடைய தடைகளிலிருந்து நீங்கள் விலகி இருக்காவிட்டால் உங்கள் மீது வந்திருக்கக்கூடிய வேதனையிலிருந்து உங்களைப் பாதுகாப்பான்' என்பதாகும். அல்லாஹ்வுக்குக் கீழ்ப்படிதல், நற்செயல்கள் புரிதல் மற்றும் இரத்த உறவுகளைப் பேணி நடத்தல் ஆகியவை ஒரு மனிதனின் ஆயுளை உண்மையாகவே அதிகரிக்கின்றன என்று கூறுபவர்களுக்கு இந்த வசனம் ஆதாரமாக அமைகிறது. இது பின்வரும் ஹதீஸில் கூறப்பட்டுள்ளதைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">صِلَةُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِمِ</span> <span class=\"quran-arabic-font text-success\">تَزِيدُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْعُمُر</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இரத்த உறவுகளைப் பேணி நடப்பது ஆயுளை அதிகமாக்கும்.)<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَجَلَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">جَاءَ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُؤَخَّرُ</span> <span class=\"quran-arabic-font text-success\">ۖ</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ்வின் தவணை வந்துவிட்டால், அது பிற்படுத்தப்பட மாட்டாது; நீங்கள் இதை அறிந்திருக்க வேண்டாமா?) இதன் பொருள்: அல்லாஹ்வின் தண்டனை வருவதற்கு முன்னரே அவனுக்குக் கீழ்ப்படிவதில் விரைந்து செயல்படுங்கள். ஏனெனில், தண்டனை நிகழ வேண்டும் என்று அவன் கட்டளையிட்டுவிட்டால், அதைத் தடுத்து நிறுத்தவோ அல்லது தள்ளிப்போடவோ முடியாது. ஏனெனில், அவனே அனைத்தையும் அடக்கி ஆளும் மாபெரும் அதிபதி; அவன் யாவற்றையும் மிகைத்தவன், அவனது வல்லமைக்கு அனைத்துப் படைப்புகளும் தலைவணங்குகின்றன.<br />\r\n<br />","text":"இது மக்காவில் அருளப்பட்டது  (வசனங்கள்: 28)\n\r\n\n\r\n﴾بِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ ﴿\n\r\n\n\r\n(அளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.)\n\r\n\n\r\nநூஹ் (அலை) அவர்கள் தம் மக்களுக்கு விடுத்த அழைப்பு\n\r\n\n\r\nநூஹ் (அலை) அவர்களைப் பற்றி அல்லாஹ் கூறுகிறான்: அவர்களுக்கு வேதனை வருவதற்கு முன்பே அல்லாஹ்வின் தண்டனையைக் குறித்து அவர்களை எச்சரிக்குமாறு கட்டளையிட்டு, அவர்களை அவர்களின் சமூகத்தாரிடம் அல்லாஹ் அனுப்பினான். அவர்கள் மனம் வருந்தி (தவ்பா செய்து) அல்லாஹ்வின் பக்கம் திரும்பினால், அந்தத் தண்டனை அவர்களை விட்டு நீக்கப்படும் என்று அவர்கள் தம் மக்களிடம் கூற வேண்டியிருந்தது. இதற்காகவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾إِنَّا أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ * قَالَ يَا قَوْمِ إِنِّي لَكُمْ نَذِيرٌ مُّبِينٌ﴿\n\r\n\n\r\n(\"உமது சமூகத்தாருக்குத் துன்புறுத்தும் வேதனை வருவதற்கு முன்னதாக, நீர் அவர்களை எச்சரிக்கை செய்வீராக\" (என்று நாம் கட்டளையிட்டோம்). அதற்கு அவர்கள் கூறினார்கள்: \"என் சமூகத்தாரே! நிச்சயமாக நான் உங்களுக்குத் தெளிவாக எச்சரிக்கை செய்பவன்.\") அதாவது, எச்சரிக்கையைத் தெளிவுபடுத்துதல் மற்றும் விஷயத்தை வெளிப்படையாகவும் தெளிவாகவும் விளக்குதல் ஆகும்.\n\r\n\n\r\n﴾أَنِ اعْبُدُواْ اللَّهَ وَاتَّقُوهُ﴿\n\r\n\n\r\n(நீங்கள் அல்லாஹ்வையே வணங்குங்கள்; அவனுக்கு அஞ்சி (தக்வாவுடன்) நடந்து கொள்ளுங்கள்,) அதாவது, 'அவன் தடை செய்தவற்றை விட்டுவிடுங்கள், அவன் பாவம் என்று அறிவித்தவற்றைத் தவிர்த்து விடுங்கள்' என்பதாகும்.\n\r\n\n\r\n﴾وَأَطِيعُونِ﴿\n\r\n\n\r\n(மேலும், எனக்குக் கீழ்ப்படியுங்கள்,) 'நான் உங்களுக்குக் கட்டளையிடுபவற்றிலும், உங்களைத் தடுப்பவற்றிலும் எனக்குக் கட்டுப்படுங்கள்.'\n\r\n\n\r\n﴾يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ﴿\n\r\n\n\r\n(அவன் உங்கள் பாவங்களை மன்னிப்பான்) அதாவது, 'நான் உங்களுக்குக் கட்டளையிட்டதை நீங்கள் செய்து, எச் செய்தியுடன் நான் உங்களிடம் அனுப்பப்பட்டேனோ அதை நீங்கள் விசுவாசித்தால் (ஈமான் கொண்டால்), அல்லாஹ் உங்கள் பாவங்களை மன்னிப்பான்' என்பதாகும்.\n\r\n\n\r\n﴾وَيُؤَخِّرْكُمْ إِلَىٰ أَجَلٍ مُّسَمًّى﴿\n\r\n\n\r\n(மேலும், ஒரு குறிப்பிட்ட காலம் வரை உங்களுக்கு அவகாசம் அளிப்பான்.) அதாவது, 'அவன் உங்கள் ஆயுளை நீட்டிப்பான்; அவனுடைய தடைகளிலிருந்து நீங்கள் விலகி இருக்காவிட்டால் உங்கள் மீது வந்திருக்கக்கூடிய வேதனையிலிருந்து உங்களைப் பாதுகாப்பான்' என்பதாகும். அல்லாஹ்வுக்குக் கீழ்ப்படிதல், நற்செயல்கள் புரிதல் மற்றும் இரத்த உறவுகளைப் பேணி நடத்தல் ஆகியவை ஒரு மனிதனின் ஆயுளை உண்மையாகவே அதிகரிக்கின்றன என்று கூறுபவர்களுக்கு இந்த வசனம் ஆதாரமாக அமைகிறது. இது பின்வரும் ஹதீஸில் கூறப்பட்டுள்ளதைப் போன்றதாகும்:\n\r\n\n\r\n﴾«صِلَةُ الرَّحِمِ تَزِيدُ فِي الْعُمُر»﴿\n\r\n\n\r\n(இரத்த உறவுகளைப் பேணி நடப்பது ஆயுளை அதிகமாக்கும்.)\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\n﴾إِنَّ أَجَلَ اللَّهِ إِذَا جَاءَ لَا يُؤَخَّرُ ۖ لَوْ كُنتُمْ تَعْلَمُونَ﴿\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ்வின் தவணை வந்துவிட்டால், அது பிற்படுத்தப்பட மாட்டாது; நீங்கள் இதை அறிந்திருக்க வேண்டாமா?) இதன் பொருள்: அல்லாஹ்வின் தண்டனை வருவதற்கு முன்னரே அவனுக்குக் கீழ்ப்படிவதில் விரைந்து செயல்படுங்கள். ஏனெனில், தண்டனை நிகழ வேண்டும் என்று அவன் கட்டளையிட்டுவிட்டால், அதைத் தடுத்து நிறுத்தவோ அல்லது தள்ளிப்போடவோ முடியாது. ஏனெனில், அவனே அனைத்தையும் அடக்கி ஆளும் மாபெரும் அதிபதி; அவன் யாவற்றையும் மிகைத்தவன், அவனது வல்லமைக்கு அனைத்துப் படைப்புகளும் தலைவணங்குகின்றன."},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=20\" class=\"link\">71:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:20 ஐ பார்க்கவும்"},"20":{"html":"<strong>நூஹ் (அலை) அவர்கள் தமது சமூகத்தினருடனான அனுபவம் குறித்து முறையிடுகிறார்கள்</strong><br />\r\n<br />\r\nஅல்லாஹ் தனது அடியாரும் தூதருமான நூஹ் (அலை) அவர்களைப் பற்றியும், அவர்கள் தமது மக்களிடமிருந்து பெற்ற பதில் குறித்துத் தனது இறைவனிடம் முறையிட்டது பற்றியும், தொள்ளாயிரத்து ஐம்பது ஆண்டுகள் என்ற இந்த நீண்ட காலத்தை அவர்கள் எவ்வளவு பொறுமையுடன் எதிர்கொண்டார்கள் என்பது குறித்தும் கூறுகிறான். அவர்களுக்குச் சத்தியத்தைத் தெளிவுபடுத்தி விளக்கியதாலும், நேர்வழி மற்றும் நேரான பாதையின் பக்கம் அவர்களை அழைத்ததாலும் நூஹ் (அலை) அவர்கள் இவ்வாறு முறையிட்டார்கள்: <span class=\"quran-arabic-font text-success\">﴾رَبِّ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">دَعَوْتُ</span> <span class=\"quran-arabic-font text-success\">قَوْمِى</span> <span class=\"quran-arabic-font text-success\">لَيْلاً</span> <span class=\"quran-arabic-font text-success\">وَنَهَاراً﴿</span><br />\r\n<br />\r\n(என் இறைவனே! நிச்சயமாக நான் என் சமூகத்தினரை இரவும் பகலும் அழைத்தேன்,) அதாவது, 'உனது கட்டளையை நிறைவேற்றுவதிலும் உனக்குக் கீழ்ப்படிவதிலும் நான் சோர்வடையாமல் இரவும் பகலும் அவர்களைத் தொடர்ந்து அழைத்தேன்.' <span class=\"quran-arabic-font text-success\">﴾فَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَزِدْهُمْ</span> <span class=\"quran-arabic-font text-success\">دُعَآئِى</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فِرَاراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஆனால் எனது அழைப்பு (அவர்களுடைய) வெறுப்பால் வெருண்டோடுதலையே தவிர வேறெதையும் அதிகப்படுத்தவில்லை.) அதாவது, 'நான் அவர்களைச் சத்தியத்தின் பக்கம் வர எவ்வளவு அழைத்தேனோ, அவ்வளவு அதிகமாக அவர்கள் அதிலிருந்து விலகிச் சென்றார்கள்.' <span class=\"quran-arabic-font text-success\">﴾وَإِنِّى</span> <span class=\"quran-arabic-font text-success\">كُلَّمَا</span> <span class=\"quran-arabic-font text-success\">دَعَوْتُهُمْ</span> <span class=\"quran-arabic-font text-success\">لِتَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">جَعَلُواْ</span> <span class=\"quran-arabic-font text-success\">أَصَابِعَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ءَاذَنِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَاسْتَغْشَوْاْ</span> <span class=\"quran-arabic-font text-success\">ثِيَابَهُمْ﴿</span><br />\r\n<br />\r\n(மேலும் நிச்சயமாக, நீ அவர்களை மன்னிப்பதற்காக நான் அவர்களை அழைத்தபோதெல்லாம், அவர்கள் தங்களது விரல்களைத் தங்களது காதுகளில் திணித்துக் கொண்டார்கள்; தங்களது ஆடைகளால் தங்களை மூடிக்கொண்டார்கள்,) அதாவது, 'நான் அவர்களை எதன் பக்கம் அழைக்கிறேனோ, அதைக் கேட்கக் கூடாது என்பதற்காகத் தங்களது காதுகளை அடைத்துக் கொண்டார்கள்.' இது குரைஷி நிராகரிப்பாளர்களைப் பற்றி அல்லாஹ் கூறியதைப் போன்றதே ஆகும்: <span class=\"quran-arabic-font text-success\">﴾وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَسْمَعُواْ</span> <span class=\"quran-arabic-font text-success\">لِهَـذَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانِ</span> <span class=\"quran-arabic-font text-success\">وَالْغَوْاْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَغْلِبُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிராகரிப்பாளர்கள் கூறுகிறார்கள்: \"இந்தக் குர்ஆனை நீங்கள் செவியுறாதீர்கள்; அது ஓதப்படும்போது அதில் குழப்பம் செய்யுங்கள், அதன் மூலம் நீங்கள் வெற்றி பெறலாம்.\") (<a href=\"qurandisp.php?sura=41&ayah=26\" class=\"link\">41:26</a>). <span class=\"quran-arabic-font text-success\">﴾وَاسْتَغْشَوْاْ</span> <span class=\"quran-arabic-font text-success\">ثِيَابَهُمْ﴿</span><br />\r\n<br />\r\n(தங்களது ஆடைகளால் தங்களை மூடிக்கொண்டார்கள்,) இது குறித்து இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறும்போது, \"அவர் (நூஹ் (அலை)) தங்களை அடையாளம் கண்டு கொள்ளக் கூடாது என்பதற்காகப் பல்வேறு போர்வைகளைக் கொண்டு தங்களை மறைத்துக் கொண்டார்கள்\" எனக் குறிப்பிடுகிறார்கள். \"அவர் சொல்வதைச் செவியுறக் கூடாது என்பதற்காகத் தங்கள் தலைகளையும் மூடிக்கொண்டார்கள்\" என்று ஸயீத் பின் ஜுபைர் மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறியுள்ளனர். <span class=\"quran-arabic-font text-success\">﴾وَأَصَرُّواْ﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் பிடிவாதமாக இருந்தார்கள்,) அதாவது, அல்லாஹ்வுக்கு இணை வைப்பதிலும் பெரும் நிராகரிப்பிலும் அவர்கள் எந்த நிலையில் இருந்தார்களோ அதிலேயே அவர்கள் நீடித்தார்கள். <span class=\"quran-arabic-font text-success\">﴾وَاسْتَكْبَرُواْ</span> <span class=\"quran-arabic-font text-success\">اسْتِكْبَاراً﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் மிகுந்த கர்வத்துடன் பெருமையடித்தார்கள்.) அதாவது, சத்தியத்தைப் பின்பற்றுவதிலிருந்தும் அதற்குப் பணிவதிலிருந்தும் அவர்கள் முற்றிலும் விலகிவிட்டார்கள். <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">دَعَوْتُهُمْ</span> <span class=\"quran-arabic-font text-success\">جِهَـراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பின்னர் நிச்சயமாக, நான் அவர்களைப் பகிரங்கமாக அழைத்தேன்.) அதாவது, மக்கள் மத்தியில் வெளிப்படையாக அழைப்பு விடுத்தேன். <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">أَعْلَنْتُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ﴿</span><br />\r\n<br />\r\n(பின்னர் நிச்சயமாக, நான் அவர்களுக்குப் பகிரங்கமாக அறிவித்தேன்,) அதாவது, வெளிப்படையான பேச்சாலும் உயர்ந்த குரலாலும் பிரகடனம் செய்தேன். <span class=\"quran-arabic-font text-success\">﴾وَأَسْرَرْتُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">إِسْرَاراً﴿</span><br />\r\n<br />\r\n(மேலும் நான் அவர்களிடம் இரகசியமாகவும் முறையிட்டேன்.) அதாவது, அவர்களுடன் தனிப்பட்ட முறையிலும் உரையாடினேன். இவ்வாறு, அவர்கள் மீது நல்வாக்கு அதிகத் தாக்கத்தை ஏற்படுத்த வேண்டும் என்பதற்காக நூஹ் (அலை) அவர்கள் பல்வேறு வகையான பிரச்சார முறைகளைக் கையாண்டார்கள்.<br />\r\n<br />\r\n<strong>நூஹ் (அலை) அவர்கள் தனது சமூகத்தை அல்லாஹ்வின் பக்கம் அழைத்தபோது கூறியது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَقُلْتُ</span> <span class=\"quran-arabic-font text-success\">اسْتَغْفِرُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّكُمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">غَفَّاراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நான் கூறினேன்: உங்கள் இறைவனிடம் மன்னிப்புத் தேடுங்கள்; நிச்சயமாக அவன் மிக அதிகமாக மன்னிப்பவனாக இருக்கிறான்;) அதாவது, 'அவனிடம் மீளுங்கள், நீங்கள் ஈடுபட்டுள்ள தவறுகளிலிருந்து விலகி விடுங்கள். அவனிடம் உடனே பாவமன்னிப்பு (தவ்பா) கேளுங்கள்; ஏனெனில், தன்னிடம் மீண்டு வருபவர்களின் மன்னிப்பை அவன் பெரிதும் ஏற்பவன். பாவம் எதுவாக இருந்தாலும் - அது நிராகரிப்பாகவோ அல்லது இணைவைப்பாகவோ இருந்தாலும் - அவன் மன்னிப்பை ஏற்றுக்கொள்வான்.' எனவே அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾فَقُلْتُ</span> <span class=\"quran-arabic-font text-success\">اسْتَغْفِرُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّكُمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">غَفَّاراً</span> - <span class=\"quran-arabic-font text-success\">يُرْسِلِ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">مُدْرَاراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நான் கூறினேன்: உங்கள் இறைவனிடம் மன்னிப்புத் தேடுங்கள்; நிச்சயமாக அவன் மிக அதிகமாக மன்னிப்பவனாக இருக்கிறான்; அவன் உங்கள் மீது மழையைத் தொடர்ச்சியாகப் பொழியச் செய்வான்,) அதாவது, இடைவிடாத மழை. இந்த வசனத்தின் காரணமாகவே, மழை வேண்டித் தொழும் தொழுகையில் (இஸ்திஸ்கா) இந்தச் சூராவை ஓதுவது பரிந்துரைக்கப்படுகிறது (முஸ்தஹப்). இது அமீருல் முஃமினீன் உமர் இப்னு அல்-கத்தாப் (ரழி) அவர்களிடமிருந்து அறிவிக்கப்பட்டுள்ளது. அவர்கள் மழை வேண்டிப் பிரார்த்திக்க மின்பரில் ஏறியபோது, அல்லாஹ்விடம் பாவமன்னிப்புத் தேடுவதையும், பாவமன்னிப்பைக் குறிப்பிடும் குர்ஆன் வசனங்களை ஓதுவதையும் தவிர வேறெதையும் செய்யவில்லை. அவ்வாறு ஓதிய வசனங்களில் இதுவும் ஒன்று: <span class=\"quran-arabic-font text-success\">﴾فَقُلْتُ</span> <span class=\"quran-arabic-font text-success\">اسْتَغْفِرُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّكُمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">غَفَّاراً</span> - <span class=\"quran-arabic-font text-success\">يُرْسِلِ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">مُدْرَاراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நான் கூறினேன்: உங்கள் இறைவனிடம் மன்னிப்புக் கோருங்கள்; நிச்சயமாக அவன் மிக அதிகமாக மன்னிப்பவன்; அவன் உங்கள் மீது மழையைத் தொடர்ச்சியாகப் பொழியச் செய்வான்.) பின்னர் உமர் (ரழி) அவர்கள் கூறினார்கள், \"நிச்சயமாக, மழையைப் பொழியச் செய்யும் வானத்தின் திறவுகோல்களைக் கொண்டே நான் மழையைத் தேடினேன்.\" \"மித்ரார் (Midrar) என்பது மழையின் ஒரு பகுதி மற்றொன்றைத் தொடர்ந்து பெய்வதைக் குறிக்கும்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்களும் மற்றவர்களும் கூறியுள்ளனர். அல்லாஹ்வின் இந்த வசனத்தைப் பொறுத்தவரை: <span class=\"quran-arabic-font text-success\">﴾وَيُمْدِدْكُمْ</span> <span class=\"quran-arabic-font text-success\">بِأَمْوَالٍ</span> <span class=\"quran-arabic-font text-success\">وَبَنِينَ</span> <span class=\"quran-arabic-font text-success\">وَيَجْعَل</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span> <span class=\"quran-arabic-font text-success\">جَنَّاتٍ</span> <span class=\"quran-arabic-font text-success\">وَيَجْعَل</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span> <span class=\"quran-arabic-font text-success\">أَنْهَاراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் உங்களுக்குச் செல்வத்தையும் புதல்வர்களையும் கொண்டு அவன் உதவி செய்வான்; உங்களுக்காகத் தோட்டங்களை உண்டாக்குவான்; உங்களுக்காக ஆறுகளையும் ஓடச் செய்வான்.) அதாவது, 'நீங்கள் அல்லாஹ்விடம் பாவமன்னிப்புத் தேடி, அவனிடம் மன்னிப்புக் கோரி அவனுக்குக் கீழ்ப்படிந்தால், அவன் உங்களுடைய வாழ்வாதாரத்தைப் பெருக்குவான்; வானத்தின் அருட்கொடைகளிலிருந்து உங்களுக்குத் தண்ணீரை வழங்குவான். பூமியின் விளைச்சல்களையும் பயிர்களையும் உங்களுக்காக வளரச் செய்வான். உங்கள் கால்நடைகளை அதிகப்படுத்துவான்; உங்களுக்கு மேன்மேலும் செல்வத்தையும் பிள்ளைகளையும் வழங்குவான். அதாவது, அவன் உங்களுக்கு அதிகச் செல்வத்தையும், அதிகச் சந்ததிகளையும், பல்வேறு கனிவர்க்கங்கள் நிறைந்த சோலைகளையும் அருள்வான். அந்தச் சோலைகளுக்கு இடையே ஆறுகளையும் ஓடச் செய்வான்.' இது ஊக்கப்படுத்தும் (நற்செய்தி கூறும்) அழைப்பு முறையாகும். பின்னர், அவன் அச்சுறுத்தலைக் கையாண்டு இதனைச் சமநிலைப்படுத்தினான். அவன் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾مَّا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَرْجُونَ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">وَقَاراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உங்களுக்கு என்ன நேர்ந்தது? அல்லாஹ்வுக்குரிய மகத்துவத்தை (கண்ணியத்தை) நீங்கள் ஏன் எதிர்பார்க்கவில்லை?) அதாவது, அவனது மகத்தான கம்பீரம். இதனை இப்னு அப்பாஸ் (ரழி), முஜாஹித் மற்றும் அத்-தஹ்ஹாக் ஆகியோர் கூறியுள்ளனர். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள், \"அல்லாஹ் கண்ணியப்படுத்தப்பட வேண்டிய தகுந்த முறையில் நீங்கள் அவனை மகத்துவப்படுத்தவில்லை. அதாவது, அவனது தண்டனைக்கும் அவனது பழிவாங்கலுக்கும் நீங்கள் அஞ்சவில்லை.\" <span class=\"quran-arabic-font text-success\">﴾وَقَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَقَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَطْوَاراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உங்களை அவன் பல்வேறு நிலைகளில் (அத்வாராக) படைத்திருக்கும் நிலையில்.) இது ஒரு விந்துத் துளியிலிருந்தும், பின்னர் அலக் (கரு) நிலையிலும், பின்னர் ஒரு தசைப்பிண்டமாகவும் உங்களைப் படைத்ததைக் குறிக்கும் என்று இப்னு அப்பாஸ் (ரழி), இக்ரிமா, கத்தாதா, யஹ்யா பின் ராஃபி, அஸ்-ஸுத்தி மற்றும் இப்னு ஸைத் ஆகியோர் கூறியுள்ளனர்.<br />\r\n<br />\r\nஅல்லாஹ்வின் வசனத்தைப் பொறுத்தவரை: <span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَوْاْ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">سَبْعَ</span> <span class=\"quran-arabic-font text-success\">سَمَاوَاتٍ</span> <span class=\"quran-arabic-font text-success\">طِبَاقاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அல்லாஹ் ஏழு வானங்களை அடுக்கடுக்காக எவ்வாறு படைத்துள்ளான் என்பதை நீங்கள் பார்க்கவில்லையா?) அதாவது, ஒன்றன் மேல் ஒன்றாக. இதனை வெறும் செவிவழிச் செய்தியாக மட்டும் அறிந்து கொள்ள வேண்டுமா அல்லது கோள்களின் இயக்கம் மற்றும் கிரகணங்களைப் போன்ற புலன்களால் உணரக்கூடிய அறிவியல்பூர்வமான விஷயமா? இது குறித்து அறிஞர்களிடையே பல்வேறு கருத்துக்கள் உள்ளன, அவற்றை நாம் இங்கே விவாதிக்கப் போவதில்லை. இங்கே அல்லாஹ்வின் நோக்கம் என்னவென்றால்: <span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَوْاْ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">سَبْعَ</span> <span class=\"quran-arabic-font text-success\">سَمَاوَاتٍ</span> <span class=\"quran-arabic-font text-success\">طِبَاقاً</span> - <span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">الْقَمَرَ</span> <span class=\"quran-arabic-font text-success\">فِيهِنَّ</span> <span class=\"quran-arabic-font text-success\">نُوراً</span> <span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسَ</span> <span class=\"quran-arabic-font text-success\">سِرَاجاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அல்லாஹ் ஏழு வானங்களை அடுக்கடுக்காகப் படைத்து, அவற்றில் சந்திரனை ஒளியாகவும், சூரியனை ஒரு விளக்காகவும் ஆக்கியுள்ளான்) அதாவது, சூரியன் மற்றும் சந்திரனின் ஒளியில் அவன் ஒரு வேறுபாட்டை ஏற்படுத்தியுள்ளான். இரவும் பகலும் அறியப்படுவதற்காக ஒவ்வொன்றையும் ஒரு தனித்துவமான பண்புடன் ஒரு குறிப்பிட்ட முறையில் அவன் அமைத்தான். சூரியன் உதிப்பதையும் மறைவதையும் கொண்டு இரவும் பகலும் அறியப்படுகின்றன. சந்திரனுக்கு அவன் குறிப்பிட்ட நிலைகளையும் இடங்களையும் நிர்ணயித்தான். அதன் ஒளி சில நேரங்களில் அதிகரித்து முழுமையை அடையும்; பின்னர் அது முற்றிலும் மறையும் வரை குறையத் தொடங்கும். இது மாதங்கள் மற்றும் ஆண்டுகள் கடந்து செல்வதைக் காட்டுகிறது. அல்லாஹ் இவ்வாறு கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾هُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسَ</span> <span class=\"quran-arabic-font text-success\">ضِيَآءً</span> <span class=\"quran-arabic-font text-success\">وَالْقَمَرَ</span> <span class=\"quran-arabic-font text-success\">نُوراً</span> <span class=\"quran-arabic-font text-success\">وَقَدَّرَهُ</span> <span class=\"quran-arabic-font text-success\">مَنَازِلَ</span> <span class=\"quran-arabic-font text-success\">لِتَعْلَمُواْ</span> <span class=\"quran-arabic-font text-success\">عَدَدَ</span> <span class=\"quran-arabic-font text-success\">السِّنِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْحِسَابَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span> <span class=\"quran-arabic-font text-success\">يُفَصِّلُ</span> <span class=\"quran-arabic-font text-success\">الْآيَاتِ</span> <span class=\"quran-arabic-font text-success\">لِقَوْمٍ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவனே சூரியனைப் பிரகாசமானதாகவும், சந்திரனை ஒளியாகவும் ஆக்கினான். மேலும் நீங்கள் ஆண்டுகளின் எண்ணிக்கையையும் கணக்கையும் அறிந்து கொள்வதற்காக அதற்கு நிலைகளை நிர்ணயித்தான். அல்லாஹ் இதனை உண்மையைக் கொண்டே படைத்தான். அறிவுள்ள மக்களுக்கு அவன் தனது வசனங்களை விரிவாக விளக்குகிறான்.) (<a href=\"qurandisp.php?sura=10&ayah=5\" class=\"link\">10:5</a>) அல்லாஹ்வின் வசனத்தைப் பொறுத்தவரை: <span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَنبَتَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">نَبَاتاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ் உங்களைப் பூமியிலிருந்து (ஒரு தாவரத்தைப் போல) முளைக்கச் செய்தான்.) இங்கு 'நபத்' (Nabat) என்பது வலியுறுத்தலுக்காகப் பயன்படுத்தப்பட்டுள்ள ஒரு வினைப்பெயர்ச்சொல் ஆகும்; இதன் பயன்பாடு இங்கு மிகச் சிறப்பாக அமைந்துள்ளது. <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُعِيدُكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا﴿</span><br />\r\n<br />\r\n(பின்னர் அவன் உங்களை அதிலேயே மீண்டும் சேர்ப்பான்,) (<a href=\"qurandisp.php?sura=71&ayah=18\" class=\"link\">71:18</a>) அதாவது, நீங்கள் மரணமடையும் போது. <span class=\"quran-arabic-font text-success\">﴾وَيُخْرِجُكُمْ</span> <span class=\"quran-arabic-font text-success\">إِخْرَاجاً﴿</span><br />\r\n<br />\r\n(மேலும் உங்களை (மீண்டும்) வெளிப்படுத்துவான்.) அதாவது, மறுமை நாளில் அவன் உங்களை முதலில் படைத்தது போலவே மீண்டும் உயிர்ப்பிப்பான். <span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">بِسَاطاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ் பூமியை உங்களுக்கு ஒரு விரிப்பாக ஆக்கினான்.) அதாவது, அவன் அதனை விரித்து, சமப்படுத்தி, உயர்ந்த மலைகளைக் கொண்டு அதனை நிலைப்படுத்தினான். <span class=\"quran-arabic-font text-success\">﴾لِّتَسْلُكُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">سُبُلاً</span> <span class=\"quran-arabic-font text-success\">فِجَاجاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அதில் நீங்கள் விசாலமான பாதைகளில் செல்வதற்காக.) அதாவது, நீங்கள் அதில் குடியேறவும், அதன் பல்வேறு திசைகள் மற்றும் பகுதிகளுக்கு நீங்கள் விரும்பியவாறு பயணம் செய்யவும் அவன் அதைப் படைத்தான். இவை அனைத்தும் வானங்களையும் பூமியையும் படைப்பதில் அல்லாஹ்வின் ஆற்றல் மற்றும் அவனது மகத்துவத்தைப் பற்றி நூஹ் (அலை) அவர்கள் அம்மக்களுக்குத் தெரிவித்த செய்திகளாகும். இது வானுலகப் பயன்களையும் பூவுலகப் பயன்களையும் வழங்கி அவன் அவர்களுக்குச் செய்த அருட்கொடைகளை வெளிப்படுத்துகிறது. ஏனெனில், அவனே படைப்பவனாகவும் பராமரிப்பவனாகவும் இருக்கிறான்; அவனே வானத்தை ஒரு கூரையாகவும் பூமியை ஒரு விரிப்பாகவும் ஆக்கினான்; தனது படைப்புகளுக்குத் தனது வாழ்வாதாரத்தை விசாலமாக்கினான். எனவே, அவனையே வணங்குவது கடமையாகும், அவனையே ஒரே இறைவனாக ஏற்றுக் கொள்ள வேண்டும். அவனுக்கு எவரையும் இணையாகக் கருதக்கூடாது; ஏனெனில் அவனுக்கு நிகரோ, சமமானவரோ, போட்டியாளரோ, இணையானவரோ, துணைவியோ, மகனோ, அமைச்சரோ அல்லது ஆலோசகரோ எவருமில்லை. மாறாக, அவனே மிக உயர்ந்தவன், மிக மகத்தானவன். <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">نُوحٌ</span> <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">عَصَوْنِى</span> <span class=\"quran-arabic-font text-success\">وَاتَّبَعُواْ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">يَزِدْهُ</span> <span class=\"quran-arabic-font text-success\">مَالُهُ</span> <span class=\"quran-arabic-font text-success\">وَوَلَدُهُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">خَسَاراً</span> - <span class=\"quran-arabic-font text-success\">وَمَكَرُواْ</span> <span class=\"quran-arabic-font text-success\">مَكْراً</span> <span class=\"quran-arabic-font text-success\">كُبَّاراً</span> - <span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَذَرُنَّ</span> <span class=\"quran-arabic-font text-success\">ءَالِهَتَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَذَرُنَّ</span> <span class=\"quran-arabic-font text-success\">وَدّاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">سُوَاعاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَغُوثَ</span> <span class=\"quran-arabic-font text-success\">وَيَعُوقَ</span> <span class=\"quran-arabic-font text-success\">وَنَسْراً</span> - <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَضَلُّواْ</span> <span class=\"quran-arabic-font text-success\">كَثِيراً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَزِدِ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">ضَلاَلاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நூஹ் கூறினார்: \"என் இறைவனே! நிச்சயமாக அவர்கள் எனக்கு மாறுசெய்தார்கள்; எவனுக்கு அவனது செல்வமும் அவனது மக்களும் நஷ்டத்தையன்றி (வேறெதனையும்) அதிகப்படுத்தவில்லையோ அவனையுமே அவர்கள் பின்பற்றினார்கள்.) (மேலும் அவர்கள் மிகப் பெரும் சூழ்ச்சி செய்தார்கள்.) (இன்னும் அவர்கள் கூறினார்கள்: \"நீங்கள் உங்கள் தெய்வங்களை விட்டுவிடாதீர்கள்; வத், ஸுவாவு, யகூஸ், யவூக் மற்றும் நஸ்ர் ஆகியவற்றையும் நீங்கள் விட்டுவிடாதீர்கள்.\") (\"மேலும் அவர்கள் அநேகரை வழி கெடுத்துவிட்டனர்; எனவே (இவ்வக்கிரமக்காரர்களான) அநியாயக்காரர்களுக்கு வழிகேட்டையன்றி (வேறெதனையும்) நீ அதிகப்படுத்தாதே!\")<br />\r\n<br />","text":"நூஹ் (அலை) அவர்கள் தமது சமூகத்தினருடனான அனுபவம் குறித்து முறையிடுகிறார்கள்\n\r\n\n\r\nஅல்லாஹ் தனது அடியாரும் தூதருமான நூஹ் (அலை) அவர்களைப் பற்றியும், அவர்கள் தமது மக்களிடமிருந்து பெற்ற பதில் குறித்துத் தனது இறைவனிடம் முறையிட்டது பற்றியும், தொள்ளாயிரத்து ஐம்பது ஆண்டுகள் என்ற இந்த நீண்ட காலத்தை அவர்கள் எவ்வளவு பொறுமையுடன் எதிர்கொண்டார்கள் என்பது குறித்தும் கூறுகிறான். அவர்களுக்குச் சத்தியத்தைத் தெளிவுபடுத்தி விளக்கியதாலும், நேர்வழி மற்றும் நேரான பாதையின் பக்கம் அவர்களை அழைத்ததாலும் நூஹ் (அலை) அவர்கள் இவ்வாறு முறையிட்டார்கள்: ﴾رَبِّ إِنِّى دَعَوْتُ قَوْمِى لَيْلاً وَنَهَاراً﴿\n\r\n\n\r\n(என் இறைவனே! நிச்சயமாக நான் என் சமூகத்தினரை இரவும் பகலும் அழைத்தேன்,) அதாவது, 'உனது கட்டளையை நிறைவேற்றுவதிலும் உனக்குக் கீழ்ப்படிவதிலும் நான் சோர்வடையாமல் இரவும் பகலும் அவர்களைத் தொடர்ந்து அழைத்தேன்.' ﴾فَلَمْ يَزِدْهُمْ دُعَآئِى إِلاَّ فِرَاراً ﴿\n\r\n\n\r\n(ஆனால் எனது அழைப்பு (அவர்களுடைய) வெறுப்பால் வெருண்டோடுதலையே தவிர வேறெதையும் அதிகப்படுத்தவில்லை.) அதாவது, 'நான் அவர்களைச் சத்தியத்தின் பக்கம் வர எவ்வளவு அழைத்தேனோ, அவ்வளவு அதிகமாக அவர்கள் அதிலிருந்து விலகிச் சென்றார்கள்.' ﴾وَإِنِّى كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُواْ أَصَابِعَهُمْ فِى ءَاذَنِهِمْ وَاسْتَغْشَوْاْ ثِيَابَهُمْ﴿\n\r\n\n\r\n(மேலும் நிச்சயமாக, நீ அவர்களை மன்னிப்பதற்காக நான் அவர்களை அழைத்தபோதெல்லாம், அவர்கள் தங்களது விரல்களைத் தங்களது காதுகளில் திணித்துக் கொண்டார்கள்; தங்களது ஆடைகளால் தங்களை மூடிக்கொண்டார்கள்,) அதாவது, 'நான் அவர்களை எதன் பக்கம் அழைக்கிறேனோ, அதைக் கேட்கக் கூடாது என்பதற்காகத் தங்களது காதுகளை அடைத்துக் கொண்டார்கள்.' இது குரைஷி நிராகரிப்பாளர்களைப் பற்றி அல்லாஹ் கூறியதைப் போன்றதே ஆகும்: ﴾وَقَالَ الَّذِينَ كَفَرُواْ لاَ تَسْمَعُواْ لِهَـذَا الْقُرْءَانِ وَالْغَوْاْ فِيهِ لَعَلَّكُمْ تَغْلِبُونَ ﴿\n\r\n\n\r\n(நிராகரிப்பாளர்கள் கூறுகிறார்கள்: \"இந்தக் குர்ஆனை நீங்கள் செவியுறாதீர்கள்; அது ஓதப்படும்போது அதில் குழப்பம் செய்யுங்கள், அதன் மூலம் நீங்கள் வெற்றி பெறலாம்.\") (41:26). ﴾وَاسْتَغْشَوْاْ ثِيَابَهُمْ﴿\n\r\n\n\r\n(தங்களது ஆடைகளால் தங்களை மூடிக்கொண்டார்கள்,) இது குறித்து இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறும்போது, \"அவர் (நூஹ் (அலை)) தங்களை அடையாளம் கண்டு கொள்ளக் கூடாது என்பதற்காகப் பல்வேறு போர்வைகளைக் கொண்டு தங்களை மறைத்துக் கொண்டார்கள்\" எனக் குறிப்பிடுகிறார்கள். \"அவர் சொல்வதைச் செவியுறக் கூடாது என்பதற்காகத் தங்கள் தலைகளையும் மூடிக்கொண்டார்கள்\" என்று ஸயீத் பின் ஜுபைர் மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறியுள்ளனர். ﴾وَأَصَرُّواْ﴿\n\r\n\n\r\n(மேலும் அவர்கள் பிடிவாதமாக இருந்தார்கள்,) அதாவது, அல்லாஹ்வுக்கு இணை வைப்பதிலும் பெரும் நிராகரிப்பிலும் அவர்கள் எந்த நிலையில் இருந்தார்களோ அதிலேயே அவர்கள் நீடித்தார்கள். ﴾وَاسْتَكْبَرُواْ اسْتِكْبَاراً﴿\n\r\n\n\r\n(மேலும் அவர்கள் மிகுந்த கர்வத்துடன் பெருமையடித்தார்கள்.) அதாவது, சத்தியத்தைப் பின்பற்றுவதிலிருந்தும் அதற்குப் பணிவதிலிருந்தும் அவர்கள் முற்றிலும் விலகிவிட்டார்கள். ﴾ثُمَّ إِنِّى دَعَوْتُهُمْ جِهَـراً ﴿\n\r\n\n\r\n(பின்னர் நிச்சயமாக, நான் அவர்களைப் பகிரங்கமாக அழைத்தேன்.) அதாவது, மக்கள் மத்தியில் வெளிப்படையாக அழைப்பு விடுத்தேன். ﴾ثُمَّ إِنِّى أَعْلَنْتُ لَهُمْ﴿\n\r\n\n\r\n(பின்னர் நிச்சயமாக, நான் அவர்களுக்குப் பகிரங்கமாக அறிவித்தேன்,) அதாவது, வெளிப்படையான பேச்சாலும் உயர்ந்த குரலாலும் பிரகடனம் செய்தேன். ﴾وَأَسْرَرْتُ لَهُمْ إِسْرَاراً﴿\n\r\n\n\r\n(மேலும் நான் அவர்களிடம் இரகசியமாகவும் முறையிட்டேன்.) அதாவது, அவர்களுடன் தனிப்பட்ட முறையிலும் உரையாடினேன். இவ்வாறு, அவர்கள் மீது நல்வாக்கு அதிகத் தாக்கத்தை ஏற்படுத்த வேண்டும் என்பதற்காக நூஹ் (அலை) அவர்கள் பல்வேறு வகையான பிரச்சார முறைகளைக் கையாண்டார்கள்.\n\r\n\n\r\nநூஹ் (அலை) அவர்கள் தனது சமூகத்தை அல்லாஹ்வின் பக்கம் அழைத்தபோது கூறியது\n\r\n\n\r\n﴾فَقُلْتُ اسْتَغْفِرُواْ رَبَّكُمْ إِنَّهُ كَانَ غَفَّاراً ﴿\n\r\n\n\r\n(நான் கூறினேன்: உங்கள் இறைவனிடம் மன்னிப்புத் தேடுங்கள்; நிச்சயமாக அவன் மிக அதிகமாக மன்னிப்பவனாக இருக்கிறான்;) அதாவது, 'அவனிடம் மீளுங்கள், நீங்கள் ஈடுபட்டுள்ள தவறுகளிலிருந்து விலகி விடுங்கள். அவனிடம் உடனே பாவமன்னிப்பு (தவ்பா) கேளுங்கள்; ஏனெனில், தன்னிடம் மீண்டு வருபவர்களின் மன்னிப்பை அவன் பெரிதும் ஏற்பவன். பாவம் எதுவாக இருந்தாலும் - அது நிராகரிப்பாகவோ அல்லது இணைவைப்பாகவோ இருந்தாலும் - அவன் மன்னிப்பை ஏற்றுக்கொள்வான்.' எனவே அவர்கள் கூறினார்கள்: ﴾فَقُلْتُ اسْتَغْفِرُواْ رَبَّكُمْ إِنَّهُ كَانَ غَفَّاراً - يُرْسِلِ السَّمَآءَ عَلَيْكُمْ مُدْرَاراً ﴿\n\r\n\n\r\n(நான் கூறினேன்: உங்கள் இறைவனிடம் மன்னிப்புத் தேடுங்கள்; நிச்சயமாக அவன் மிக அதிகமாக மன்னிப்பவனாக இருக்கிறான்; அவன் உங்கள் மீது மழையைத் தொடர்ச்சியாகப் பொழியச் செய்வான்,) அதாவது, இடைவிடாத மழை. இந்த வசனத்தின் காரணமாகவே, மழை வேண்டித் தொழும் தொழுகையில் (இஸ்திஸ்கா) இந்தச் சூராவை ஓதுவது பரிந்துரைக்கப்படுகிறது (முஸ்தஹப்). இது அமீருல் முஃமினீன் உமர் இப்னு அல்-கத்தாப் (ரழி) அவர்களிடமிருந்து அறிவிக்கப்பட்டுள்ளது. அவர்கள் மழை வேண்டிப் பிரார்த்திக்க மின்பரில் ஏறியபோது, அல்லாஹ்விடம் பாவமன்னிப்புத் தேடுவதையும், பாவமன்னிப்பைக் குறிப்பிடும் குர்ஆன் வசனங்களை ஓதுவதையும் தவிர வேறெதையும் செய்யவில்லை. அவ்வாறு ஓதிய வசனங்களில் இதுவும் ஒன்று: ﴾فَقُلْتُ اسْتَغْفِرُواْ رَبَّكُمْ إِنَّهُ كَانَ غَفَّاراً - يُرْسِلِ السَّمَآءَ عَلَيْكُمْ مُدْرَاراً ﴿\n\r\n\n\r\n(நான் கூறினேன்: உங்கள் இறைவனிடம் மன்னிப்புக் கோருங்கள்; நிச்சயமாக அவன் மிக அதிகமாக மன்னிப்பவன்; அவன் உங்கள் மீது மழையைத் தொடர்ச்சியாகப் பொழியச் செய்வான்.) பின்னர் உமர் (ரழி) அவர்கள் கூறினார்கள், \"நிச்சயமாக, மழையைப் பொழியச் செய்யும் வானத்தின் திறவுகோல்களைக் கொண்டே நான் மழையைத் தேடினேன்.\" \"மித்ரார் (Midrar) என்பது மழையின் ஒரு பகுதி மற்றொன்றைத் தொடர்ந்து பெய்வதைக் குறிக்கும்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்களும் மற்றவர்களும் கூறியுள்ளனர். அல்லாஹ்வின் இந்த வசனத்தைப் பொறுத்தவரை: ﴾وَيُمْدِدْكُمْ بِأَمْوَالٍ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّاتٍ وَيَجْعَل لَّكُمْ أَنْهَاراً ﴿\n\r\n\n\r\n(மேலும் உங்களுக்குச் செல்வத்தையும் புதல்வர்களையும் கொண்டு அவன் உதவி செய்வான்; உங்களுக்காகத் தோட்டங்களை உண்டாக்குவான்; உங்களுக்காக ஆறுகளையும் ஓடச் செய்வான்.) அதாவது, 'நீங்கள் அல்லாஹ்விடம் பாவமன்னிப்புத் தேடி, அவனிடம் மன்னிப்புக் கோரி அவனுக்குக் கீழ்ப்படிந்தால், அவன் உங்களுடைய வாழ்வாதாரத்தைப் பெருக்குவான்; வானத்தின் அருட்கொடைகளிலிருந்து உங்களுக்குத் தண்ணீரை வழங்குவான். பூமியின் விளைச்சல்களையும் பயிர்களையும் உங்களுக்காக வளரச் செய்வான். உங்கள் கால்நடைகளை அதிகப்படுத்துவான்; உங்களுக்கு மேன்மேலும் செல்வத்தையும் பிள்ளைகளையும் வழங்குவான். அதாவது, அவன் உங்களுக்கு அதிகச் செல்வத்தையும், அதிகச் சந்ததிகளையும், பல்வேறு கனிவர்க்கங்கள் நிறைந்த சோலைகளையும் அருள்வான். அந்தச் சோலைகளுக்கு இடையே ஆறுகளையும் ஓடச் செய்வான்.' இது ஊக்கப்படுத்தும் (நற்செய்தி கூறும்) அழைப்பு முறையாகும். பின்னர், அவன் அச்சுறுத்தலைக் கையாண்டு இதனைச் சமநிலைப்படுத்தினான். அவன் கூறினான்: ﴾مَّا لَكُمْ لاَ تَرْجُونَ لِلَّهِ وَقَاراً ﴿\n\r\n\n\r\n(உங்களுக்கு என்ன நேர்ந்தது? அல்லாஹ்வுக்குரிய மகத்துவத்தை (கண்ணியத்தை) நீங்கள் ஏன் எதிர்பார்க்கவில்லை?) அதாவது, அவனது மகத்தான கம்பீரம். இதனை இப்னு அப்பாஸ் (ரழி), முஜாஹித் மற்றும் அத்-தஹ்ஹாக் ஆகியோர் கூறியுள்ளனர். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள், \"அல்லாஹ் கண்ணியப்படுத்தப்பட வேண்டிய தகுந்த முறையில் நீங்கள் அவனை மகத்துவப்படுத்தவில்லை. அதாவது, அவனது தண்டனைக்கும் அவனது பழிவாங்கலுக்கும் நீங்கள் அஞ்சவில்லை.\" ﴾وَقَدْ خَلَقَكُمْ أَطْوَاراً ﴿\n\r\n\n\r\n(உங்களை அவன் பல்வேறு நிலைகளில் (அத்வாராக) படைத்திருக்கும் நிலையில்.) இது ஒரு விந்துத் துளியிலிருந்தும், பின்னர் அலக் (கரு) நிலையிலும், பின்னர் ஒரு தசைப்பிண்டமாகவும் உங்களைப் படைத்ததைக் குறிக்கும் என்று இப்னு அப்பாஸ் (ரழி), இக்ரிமா, கத்தாதா, யஹ்யா பின் ராஃபி, அஸ்-ஸுத்தி மற்றும் இப்னு ஸைத் ஆகியோர் கூறியுள்ளனர்.\n\r\n\n\r\nஅல்லாஹ்வின் வசனத்தைப் பொறுத்தவரை: ﴾أَلَمْ تَرَوْاْ كَيْفَ خَلَقَ اللَّهُ سَبْعَ سَمَاوَاتٍ طِبَاقاً ﴿\n\r\n\n\r\n(அல்லாஹ் ஏழு வானங்களை அடுக்கடுக்காக எவ்வாறு படைத்துள்ளான் என்பதை நீங்கள் பார்க்கவில்லையா?) அதாவது, ஒன்றன் மேல் ஒன்றாக. இதனை வெறும் செவிவழிச் செய்தியாக மட்டும் அறிந்து கொள்ள வேண்டுமா அல்லது கோள்களின் இயக்கம் மற்றும் கிரகணங்களைப் போன்ற புலன்களால் உணரக்கூடிய அறிவியல்பூர்வமான விஷயமா? இது குறித்து அறிஞர்களிடையே பல்வேறு கருத்துக்கள் உள்ளன, அவற்றை நாம் இங்கே விவாதிக்கப் போவதில்லை. இங்கே அல்லாஹ்வின் நோக்கம் என்னவென்றால்: ﴾أَلَمْ تَرَوْاْ كَيْفَ خَلَقَ اللَّهُ سَبْعَ سَمَاوَاتٍ طِبَاقاً - وَجَعَلَ الْقَمَرَ فِيهِنَّ نُوراً وَجَعَلَ الشَّمْسَ سِرَاجاً ﴿\n\r\n\n\r\n(அல்லாஹ் ஏழு வானங்களை அடுக்கடுக்காகப் படைத்து, அவற்றில் சந்திரனை ஒளியாகவும், சூரியனை ஒரு விளக்காகவும் ஆக்கியுள்ளான்) அதாவது, சூரியன் மற்றும் சந்திரனின் ஒளியில் அவன் ஒரு வேறுபாட்டை ஏற்படுத்தியுள்ளான். இரவும் பகலும் அறியப்படுவதற்காக ஒவ்வொன்றையும் ஒரு தனித்துவமான பண்புடன் ஒரு குறிப்பிட்ட முறையில் அவன் அமைத்தான். சூரியன் உதிப்பதையும் மறைவதையும் கொண்டு இரவும் பகலும் அறியப்படுகின்றன. சந்திரனுக்கு அவன் குறிப்பிட்ட நிலைகளையும் இடங்களையும் நிர்ணயித்தான். அதன் ஒளி சில நேரங்களில் அதிகரித்து முழுமையை அடையும்; பின்னர் அது முற்றிலும் மறையும் வரை குறையத் தொடங்கும். இது மாதங்கள் மற்றும் ஆண்டுகள் கடந்து செல்வதைக் காட்டுகிறது. அல்லாஹ் இவ்வாறு கூறுகிறான்: ﴾هُوَ الَّذِى جَعَلَ الشَّمْسَ ضِيَآءً وَالْقَمَرَ نُوراً وَقَدَّرَهُ مَنَازِلَ لِتَعْلَمُواْ عَدَدَ السِّنِينَ وَالْحِسَابَ مَا خَلَقَ اللَّهُ ذَلِكَ إِلاَّ بِالْحَقِّ يُفَصِّلُ الْآيَاتِ لِقَوْمٍ يَعْلَمُونَ ﴿\n\r\n\n\r\n(அவனே சூரியனைப் பிரகாசமானதாகவும், சந்திரனை ஒளியாகவும் ஆக்கினான். மேலும் நீங்கள் ஆண்டுகளின் எண்ணிக்கையையும் கணக்கையும் அறிந்து கொள்வதற்காக அதற்கு நிலைகளை நிர்ணயித்தான். அல்லாஹ் இதனை உண்மையைக் கொண்டே படைத்தான். அறிவுள்ள மக்களுக்கு அவன் தனது வசனங்களை விரிவாக விளக்குகிறான்.) (10:5) அல்லாஹ்வின் வசனத்தைப் பொறுத்தவரை: ﴾وَاللَّهُ أَنبَتَكُمْ مِّنَ الْأَرْضِ نَبَاتاً ﴿\n\r\n\n\r\n(மேலும் அல்லாஹ் உங்களைப் பூமியிலிருந்து (ஒரு தாவரத்தைப் போல) முளைக்கச் செய்தான்.) இங்கு 'நபத்' (Nabat) என்பது வலியுறுத்தலுக்காகப் பயன்படுத்தப்பட்டுள்ள ஒரு வினைப்பெயர்ச்சொல் ஆகும்; இதன் பயன்பாடு இங்கு மிகச் சிறப்பாக அமைந்துள்ளது. ﴾ثُمَّ يُعِيدُكُمْ فِيهَا﴿\n\r\n\n\r\n(பின்னர் அவன் உங்களை அதிலேயே மீண்டும் சேர்ப்பான்,) (71:18) அதாவது, நீங்கள் மரணமடையும் போது. ﴾وَيُخْرِجُكُمْ إِخْرَاجاً﴿\n\r\n\n\r\n(மேலும் உங்களை (மீண்டும்) வெளிப்படுத்துவான்.) அதாவது, மறுமை நாளில் அவன் உங்களை முதலில் படைத்தது போலவே மீண்டும் உயிர்ப்பிப்பான். ﴾وَاللَّهُ جَعَلَ لَكُمُ الْأَرْضَ بِسَاطاً ﴿\n\r\n\n\r\n(மேலும் அல்லாஹ் பூமியை உங்களுக்கு ஒரு விரிப்பாக ஆக்கினான்.) அதாவது, அவன் அதனை விரித்து, சமப்படுத்தி, உயர்ந்த மலைகளைக் கொண்டு அதனை நிலைப்படுத்தினான். ﴾لِّتَسْلُكُواْ مِنْهَا سُبُلاً فِجَاجاً ﴿\n\r\n\n\r\n(அதில் நீங்கள் விசாலமான பாதைகளில் செல்வதற்காக.) அதாவது, நீங்கள் அதில் குடியேறவும், அதன் பல்வேறு திசைகள் மற்றும் பகுதிகளுக்கு நீங்கள் விரும்பியவாறு பயணம் செய்யவும் அவன் அதைப் படைத்தான். இவை அனைத்தும் வானங்களையும் பூமியையும் படைப்பதில் அல்லாஹ்வின் ஆற்றல் மற்றும் அவனது மகத்துவத்தைப் பற்றி நூஹ் (அலை) அவர்கள் அம்மக்களுக்குத் தெரிவித்த செய்திகளாகும். இது வானுலகப் பயன்களையும் பூவுலகப் பயன்களையும் வழங்கி அவன் அவர்களுக்குச் செய்த அருட்கொடைகளை வெளிப்படுத்துகிறது. ஏனெனில், அவனே படைப்பவனாகவும் பராமரிப்பவனாகவும் இருக்கிறான்; அவனே வானத்தை ஒரு கூரையாகவும் பூமியை ஒரு விரிப்பாகவும் ஆக்கினான்; தனது படைப்புகளுக்குத் தனது வாழ்வாதாரத்தை விசாலமாக்கினான். எனவே, அவனையே வணங்குவது கடமையாகும், அவனையே ஒரே இறைவனாக ஏற்றுக் கொள்ள வேண்டும். அவனுக்கு எவரையும் இணையாகக் கருதக்கூடாது; ஏனெனில் அவனுக்கு நிகரோ, சமமானவரோ, போட்டியாளரோ, இணையானவரோ, துணைவியோ, மகனோ, அமைச்சரோ அல்லது ஆலோசகரோ எவருமில்லை. மாறாக, அவனே மிக உயர்ந்தவன், மிக மகத்தானவன். ﴾قَالَ نُوحٌ رَّبِّ إِنَّهُمْ عَصَوْنِى وَاتَّبَعُواْ مَن لَّمْ يَزِدْهُ مَالُهُ وَوَلَدُهُ إِلاَّ خَسَاراً - وَمَكَرُواْ مَكْراً كُبَّاراً - وَقَالُواْ لاَ تَذَرُنَّ ءَالِهَتَكُمْ وَلاَ تَذَرُنَّ وَدّاً وَلاَ سُوَاعاً وَلاَ يَغُوثَ وَيَعُوقَ وَنَسْراً - وَقَدْ أَضَلُّواْ كَثِيراً وَلاَ تَزِدِ الظَّالِمِينَ إِلاَّ ضَلاَلاً ﴿\n\r\n\n\r\n(நூஹ் கூறினார்: \"என் இறைவனே! நிச்சயமாக அவர்கள் எனக்கு மாறுசெய்தார்கள்; எவனுக்கு அவனது செல்வமும் அவனது மக்களும் நஷ்டத்தையன்றி (வேறெதனையும்) அதிகப்படுத்தவில்லையோ அவனையுமே அவர்கள் பின்பற்றினார்கள்.) (மேலும் அவர்கள் மிகப் பெரும் சூழ்ச்சி செய்தார்கள்.) (இன்னும் அவர்கள் கூறினார்கள்: \"நீங்கள் உங்கள் தெய்வங்களை விட்டுவிடாதீர்கள்; வத், ஸுவாவு, யகூஸ், யவூக் மற்றும் நஸ்ர் ஆகியவற்றையும் நீங்கள் விட்டுவிடாதீர்கள்.\") (\"மேலும் அவர்கள் அநேகரை வழி கெடுத்துவிட்டனர்; எனவே (இவ்வக்கிரமக்காரர்களான) அநியாயக்காரர்களுக்கு வழிகேட்டையன்றி (வேறெதனையும்) நீ அதிகப்படுத்தாதே!\")"},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=24\" class=\"link\">71:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:24 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=24\" class=\"link\">71:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:24 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=24\" class=\"link\">71:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:24 ஐ பார்க்கவும்"},"24":{"html":"<strong>தம்முடைய சமூகத்தாரின் பதில் குறித்து நூஹ் (அலை) அவர்கள் தம் இறைவனிடம் முறையிடுதல்</strong><br />\r\n<br />\r\nயாவற்றையும் அறிந்தவனும், எதனையும் தப்பவிடாதவனுமான அல்லாஹ்விடம், தான் விடுத்த தெளிவான மற்றும் முழுமையான அழைப்பைப் பற்றி முறையிட நூஹ் (அலை) அவர்கள் முற்பட்டதாக அல்லாஹ் கூறுகிறான். அவர்கள் சில நேரங்களில் நன்மாராயம் கூறியும், சில நேரங்களில் அச்சமூட்டி எச்சரித்தும் பல்வேறு வழிகளில் அவர்களை அழைத்தார்கள். ஆயினும், அவர்கள் அவருக்குக் கீழ்ப்படியாமல், அவரை எதிர்த்துப் பொய்யாக்கினர்; மேலும் உலகாதாயத்தில் மூழ்கியிருந்தவர்களையே பின்பற்றினர். அவர்கள் அல்லாஹ்வின் கட்டளையைப் புறக்கணித்தவர்களாகவும், செல்வங்கள் மற்றும் பிள்ளைச் செல்வங்கள் வழங்கப்பட்டவர்களாகவும் இருந்தனர். எனினும், இத்தகைய உலகியல் வசதிகள் அவர்களுக்குக் கண்ணியத்தையோ அல்லது அருளையோ தருவதற்காக வழங்கப்பட்டவை அல்ல; மாறாக அவை படிப்படியான தண்டனைக்கும் தற்காலிக அவகாசத்திற்குமே வழங்கப்பட்டன. எனவேதான் அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاتَّبَعُواْ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">يَزِدْهُ</span> <span class=\"quran-arabic-font text-success\">مَالُهُ</span> <span class=\"quran-arabic-font text-success\">وَوَلَدُهُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">خَسَاراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும், எவருடைய செல்வமும் பிள்ளைகளும் அவருக்கு நஷ்டத்தைத் தவிர வேறு எதையும் அதிகரிக்கவில்லையோ, அவரையே இவர்கள் பின்பற்றினார்கள்.)<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றான,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَكَرُواْ</span> <span class=\"quran-arabic-font text-success\">مَكْراً</span> <span class=\"quran-arabic-font text-success\">كُبَّاراً</span>   <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் ஒரு பெரும் சதித்திட்டத்தைத் தீட்டினார்கள்.) என்பதன் பொருள், தாங்கள் சத்தியத்தையும் நேர்வழியையுமே பின்பற்றுவதாகத் தங்களைப் பின்பற்றுபவர்களை நம்பவைத்து ஏமாற்றுவதற்காக, அவர்கள் ஒரு வஞ்சகமான சூழ்ச்சியைச் செய்தார்கள் என்பதாகும். இது மறுமை நாளில் அவர்கள் ஒருவருக்கொருவர் கூறிக்கொள்வதைப் போன்றதாகும்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بَلْ</span> <span class=\"quran-arabic-font text-success\">مَكْرُ</span> <span class=\"quran-arabic-font text-success\">الَّيْلِ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارِ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">تَأْمُرُونَنَآ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّكْفُرَ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَنَجْعَلَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">أَندَاداً</span>  <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இல்லை, மாறாக அது உங்களுடைய இரவும் பகலுமான சூழ்ச்சியாக இருந்தது: அல்லாஹ்வை நிராகரிக்குமாறும் அவனுக்கு இணைகளை ஏற்படுத்துமாறும் நீங்கள் எங்களுக்குக் கட்டளையிட்டபோது!) (<a href=\"qurandisp.php?sura=34&ayah=33\" class=\"link\">34:33</a>) இதனால்தான் அவன் (அல்லாஹ்) இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<strong>நூஹ் (அலை) அவர்களின் சமூகத்தாரின் சிலைகளும் அவர்களுக்கு நேர்ந்தவையும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَكَرُواْ</span> <span class=\"quran-arabic-font text-success\">مَكْراً</span> <span class=\"quran-arabic-font text-success\">كُبَّاراً</span> - <span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَذَرُنَّ</span> <span class=\"quran-arabic-font text-success\">ءَالِهَتَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَذَرُنَّ</span> <span class=\"quran-arabic-font text-success\">وَدّاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">سُوَاعاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَغُوثَ</span> <span class=\"quran-arabic-font text-success\">وَيَعُوقَ</span> <span class=\"quran-arabic-font text-success\">وَنَسْراً</span>   <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் ஒரு பெரும் சதித்திட்டத்தைத் தீட்டினார்கள். மேலும் அவர்கள் கூறினார்கள்: 'உங்களுடைய கடவுள்களை நீங்கள் விட்டுவிடாதீர்கள்; வத், ஸுவா, யஃகூஸ், யஊக் மற்றும் நஸ்ர் ஆகிய சிலைகளையும் விட்டுவிடாதீர்கள்.') இவை அல்லாஹ்வையன்றி அவர்கள் வணங்கி வந்த சிலைகளின் பெயர்களாகும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக இமாம் புகாரி அவர்கள் பதிவு செய்துள்ளார்கள்: \"நூஹ் (அலை) அவர்களின் சமூகத்தாரிடம் இருந்த சிலைகள் பிற்காலத்தில் அரபிகளிடம் வந்து சேர்ந்தன. 'வத்' எனும் சிலை, தவ்மத் அல்-ஜந்தல் பகுதியில் வாழ்ந்த கல்ப் கோத்திரத்தாரின் சிலையாக மாறியது. 'ஸுவா' எனும் சிலை ஹுதைல் கோத்திரத்தாருக்கும், 'யஃகூஸ்' முராத் கோத்திரத்தாருக்கும் உரிய சிலையானது. பின்னர் ஸபா பகுதியில் உள்ள அல்-ஜுரூஃப் எனும் இடத்தில் பனீ ஃகுதைஃப் கோத்திரத்தாரும் அதை வணங்கினர். 'யஊக்' ஹம்தான் கோத்திரத்தாரின் சிலையாகவும், 'நஸ்ர்' ஹிம்யர் கோத்திரத்தில் உள்ள தூ கிலா குடும்பத்தாரின் சிலையாகவும் இருந்தது. இந்தச் சிலைகள் அனைத்தும் நூஹ் (அலை) அவர்களின் சமூகத்தில் வாழ்ந்த நல்ல மனிதர்களின் பெயர்களால் அழைக்கப்பட்டன. அவர்கள் இறந்தபோது, அவர்கள் கூடி அமர்ந்து வந்த இடங்களில் அவர்களின் நினைவாகச் சிலைகளை நிறுவுமாறும், அச்சிலைகளுக்கு அவர்களின் பெயர்களையே சூட்டுமாறும் ஷைத்தான் அந்த மக்களுக்குத் தூண்டினான். அவர்கள் அவ்வாறே செய்தனர். ஆனால், அந்த மக்கள் (அச்சிலைகளை உருவாக்கியவர்கள்) மரணித்து, அதுகுறித்த அறிவு மறைந்து போகும் வரை அச்சிலைகள் வணங்கப்படவில்லை. அதன் பின்னரே அவை வணங்கப்படலாயின.\" இது போன்ற ஒரு செய்தி இக்ரிமா, அத்-தஹ்ஹாக், கத்தாதா மற்றும் இப்னு இஸ்ஹாக் ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. அலி பின் அபீ தல்ஹா அவர்கள் இப்னு அப்பாஸ் (ரழி) வழியாக அறிவிக்கையில், \"இவை நூஹ் (அலை) அவர்களின் காலத்தில் வணங்கப்பட்ட சிலைகளாகும்\" என்று குறிப்பிட்டுள்ளார்கள். முஹம்மது பின் கைஸ் அவர்கள் யஃகூஸ், யஊக் மற்றும் நஸ்ர் ஆகிய சிலைகளைப் பற்றிக் கூறுகையில், \"இவர்கள் ஆதம் (அலை) மற்றும் நூஹ் (அலை) ஆகியோரின் காலத்திற்கு இடைப்பட்ட காலத்தில் வாழ்ந்த நல்ல மனிதர்களாவர். அவர்களைப் பின்பற்றும் ஆதரவாளர்கள் அவர்களுக்கு இருந்தனர். அவர்கள் இறந்தபோது, அவர்களைப் பின்பற்றியவர்கள்: 'அவர்களின் உருவங்களை நாம் அமைத்துக் கொண்டால், அவர்களைக் காணும்போது அது நமது வழிபாட்டு ஆர்வத்தை அதிகப்படுத்தும்' எனக் கூறி அவர்களின் உருவங்களைச் செய்தனர். பின்னர் அவர்கள் இறந்து, அவர்களுக்குப் பின் வந்த தலைமுறையினரிடம் இப்லீஸ் வந்து, 'உங்கள் முன்னோர்கள் இச்சிலைகளை வணங்கி வந்தனர்; அதன் காரணமாகவே அவர்களுக்கு மழையும் வழங்கப்பட்டது' என்று கூறினான். இவ்வாறு பிற்கால மக்கள் அவற்றை வணங்கத் தொடங்கினர்\" என்று இப்னு ஜரீர் பதிவு செய்துள்ளார்.<br />\r\n<br />\r\n<strong>தம்முடைய சமூகத்தினருக்கு எதிராகவும் தம்மை விசுவாசித்தவர்களுக்காகவும் நூஹ் (அலை) அவர்களின் பிரார்த்தனை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَضَلُّواْ</span> <span class=\"quran-arabic-font text-success\">كَثِيراً</span>  <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் நிச்சயமாக அவர்கள் பலரை வழிகெடுத்துவிட்டார்கள்.) அதாவது, அவர்கள் வணக்கத்திற்காக ஏற்படுத்திக்கொண்ட அச்சிலைகளின் மூலம் பெருவாரியான மக்களை வழிகேட்டில் தள்ளினார்கள். அந்தச் சிலைகளை வணங்கும் பழக்கம் இன்றுவரை பல தலைமுறைகளாக அரபிகளிடமும், அரபியர் அல்லாதவர்களிடமும், ஆதமுடைய மக்களிடமும் தொடர்ந்து வருகிறது. இப்ராஹீம் நபி (அலை) அவர்கள் தம் பிரார்த்தனையில் இதையே குறிப்பிட்டார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاجْنُبْنِى</span> <span class=\"quran-arabic-font text-success\">وَبَنِىَّ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّعْبُدَ</span> <span class=\"quran-arabic-font text-success\">الأَصْنَامَ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُنَّ</span> <span class=\"quran-arabic-font text-success\">أَضْلَلْنَ</span> <span class=\"quran-arabic-font text-success\">كَثِيرًا</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ﴿</span><br />\r\n<br />\r\n(என்னையும் என் புதல்வர்களையும் சிலைகளை வணங்குவதிலிருந்து விலக்கி வைப்பாயாக. என் இறைவனே! நிச்சயமாக அவை மனிதர்களில் பலரை வழிகெடுத்துவிட்டன...) (<a href=\"qurandisp.php?sura=14&ayah=35\" class=\"link\">14:35</a>,36)<br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَزِدِ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمِينَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">ضَلاَلاً</span>  <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அநியாயக்காரர்களுக்கு வழிகேட்டைத் தவிர வேறு எதையும் அதிகரிக்காதே.) இது நூஹ் (அலை) அவர்கள் தன் சமூகத்தாரின் கலகம், நிராகரிப்பு மற்றும் பிடிவாதம் காரணமாக அவர்களுக்கு எதிராகச் செய்த பிரார்த்தனையாகும். இது மூஸா (அலை) அவர்கள் ஃபிர்அவ்னுக்கும் அவனது தலைவர்களுக்கும் எதிராகச் செய்த பிரார்த்தனையைப் போன்றதேயாகும்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">اطْمِسْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَمْوَالِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَاشْدُدْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَرَوُاْ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْأَلِيمَ﴿</span><br />\r\n<br />\r\n(எங்கள் இறைவனே! அவர்களுடைய செல்வங்களை அழித்துவிடுவாயாக, அவர்களுடைய உள்ளங்களை இறுக்கிவிடுவாயாக; வேதனை தரும் நோவினையை அவர்கள் காணும் வரை அவர்கள் விசுவாசம் கொள்ள மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=10&ayah=88\" class=\"link\">10:88</a>)<br />\r\n<br />\r\nநிச்சயமாக, அல்லாஹ் இந்த இரண்டு நபிமார்களின் பிரார்த்தனையை ஏற்றுக்கொண்டான். அவர்கள் கொண்டு வந்த சத்தியத்தை அவர்கள் நிராகரித்த காரணத்தினால் அல்லாஹ் அந்தச் சமூகத்தாரை மூழ்கடித்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مِّمَّا</span> <span class=\"quran-arabic-font text-success\">خَطِيئَاتِهِمْ</span> <span class=\"quran-arabic-font text-success\">أُغْرِقُوا</span> <span class=\"quran-arabic-font text-success\">فَأُدْخِلُوا</span> <span class=\"quran-arabic-font text-success\">نَارًا</span> <span class=\"quran-arabic-font text-success\">فَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَجِدُوا</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَنصَارًا</span> - <span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">نُوحٌ</span> <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَذَرْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرِينَ</span> <span class=\"quran-arabic-font text-success\">دَيَّارًا</span> - <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">تَذَرْهُمْ</span> <span class=\"quran-arabic-font text-success\">يُضِلُّوا</span> <span class=\"quran-arabic-font text-success\">عِبَادَكَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَلِدُوا</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فَاجِرًا</span> <span class=\"quran-arabic-font text-success\">كَفَّارًا</span> - <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">وَلِوَالِدَىَّ</span> <span class=\"quran-arabic-font text-success\">وَلِمَن</span> <span class=\"quran-arabic-font text-success\">دَخَلَ</span> <span class=\"quran-arabic-font text-success\">بَيْتِىَ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنًا</span> <span class=\"quran-arabic-font text-success\">وَلِلْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُؤْمِنَاتِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَزِدِ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">تَبَارًا﴿</span><br />\r\n<br />\r\n(அவர்களுடைய பாவங்களின் காரணமாகவே அவர்கள் மூழ்கடிக்கப்பட்டு, நரகத்தில் புகுத்தப்பட்டார்கள்; அல்லாஹ்வையன்றி தங்களுக்கு உதவியாளர்கள் எவரையும் அவர்கள் காணவில்லை.<br />\r\n<br />\r\nமேலும் நூஹ் கூறினார்: \"என் இறைவனே! பூமியில் வசிப்போரில் காஃபிர்களில் எவரையும் நீ விட்டு வைக்காதே!<br />\r\n<br />\r\nநிச்சயமாக நீ அவர்களை விட்டுவைத்தால், அவர்கள் உன்னுடைய அடியார்களை வழிகெடுத்து விடுவார்கள்; மேலும் அவர்கள் பாவிகளையும், நன்றி கெட்டவர்களையுமன்றி (வேறு பிள்ளைகளைப்) பெற்றெடுக்க மாட்டார்கள்.<br />\r\n<br />\r\nஎன் இறைவனே! எனக்கும், என் பெற்றோருக்கும், முஃமினாக என் வீட்டில் நுழைந்தவர்களுக்கும், முஃமினான ஆண்களுக்கும், முஃமினான பெண்களுக்கும் நீ மன்னிப்பளிப்பாயாக! மேலும் அநியாயக்காரர்களுக்கு அழிவைத் தவிர வேறு எதையும் நீ அதிகரிக்காதே!\")<br />\r\n<br />\r\n**நூஹ் (அலை) அவர்கள் தம் இறைவனிடம் கேட்ட இறுதித் தீர்ப்பும், அது நிறைவேற்றப்பட்டதும்**<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مِّمَّا</span> <span class=\"quran-arabic-font text-success\">خَطِيئَاتِهِمْ</span> <span class=\"quran-arabic-font text-success\">أُغْرِقُوا﴿</span><br />\r\n(அவர்களுடைய பாவங்களின் காரணமாகவே அவர்கள் மூழ்கடிக்கப்பட்டு...) அதாவது அவர்களுடைய அதிகமான பாவங்கள், அத்துமீறல்கள், அல்லாஹ்வை மறுத்தல் மற்றும் அவனது தூதரை எதிர்த்தல் ஆகியவற்றின் காரணமாக அவர்கள் வெள்ளப்பெருக்கின் மூலம் மூழ்கடிக்கப்பட்டார்கள்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأُدْخِلُواْ</span> <span class=\"quran-arabic-font text-success\">نَاراً﴿</span><br />\r\n(நரகத்தில் புகுத்தப்பட்டார்கள்) அதாவது அவர்கள் மூழ்கடிக்கப்பட்ட நிலையிலிருந்து (அடுத்து வரும் பர்ஸக் வாழ்வின்) நரக நெருப்பிற்கு மாற்றப்பட்டார்கள்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَجِدُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَنصَاراً﴿</span><br />\r\n(எனவே அல்லாஹ்வைத் தவிர தங்களுக்கு உதவுபவர் எவரையும் அவர்கள் காணவில்லை) அதாவது அல்லாஹ்வின் தண்டனையிலிருந்து அவர்களைக் காப்பாற்றவோ, தடுக்கவோ அல்லது பாதுகாக்கவோ கூடிய உதவியாளர், அடைக்கலம் தருபவர் அல்லது காப்பாளர் எவரும் அவர்களுக்குக் கிடைக்கவில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَالَ</span> <span class=\"quran-arabic-font text-success\">نُوحٌ</span> <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَذَرْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرِينَ</span> <span class=\"quran-arabic-font text-success\">دَيَّارًا﴿</span><br />\r\n(மேலும் நூஹ் கூறினார்: \"என் இறைவனே! பூமியில் வசிப்போரில் காஃபிர்களில் எவரையும் நீ விட்டு வைக்காதே!\") அதாவது பூமியின் மேற்பரப்பில் நடமாடக்கூடிய அவர்களில் ஒருவரைக்கூட விட்டுவிடாதே. அல்லாஹ் அவரது பிரார்த்தனையை ஏற்றுக்கொண்டான். அவர்களில் எஞ்சியிருந்த அனைவரையும் அவன் அழித்துவிட்டான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">تَذَرْهُمْ</span> <span class=\"quran-arabic-font text-success\">يُضِلُّواْ</span> <span class=\"quran-arabic-font text-success\">عِبَادَكَ﴿</span><br />\r\n(நிச்சயமாக நீ அவர்களை விட்டுவைத்தால், அவர்கள் உன்னுடைய அடியார்களை வழிகெடுத்து விடுவார்கள்) அதாவது அவர்கள் வழிதவறியவர்களாகவும், மற்றவர்களை வழிகெடுப்பவர்களாகவும் இருப்பார்கள்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَلِدُواْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فَاجِراً</span> <span class=\"quran-arabic-font text-success\">كَفَّاراً﴿</span><br />\r\n(மேலும் அவர்கள் பாவிகளையும், நன்றி கெட்டவர்களையுமன்றி (வேறு பிள்ளைகளைப்) பெற்றெடுக்க மாட்டார்கள்) அதாவது தீயவர்களையும், (இறை)மறுப்பாளர்களையும் தவிர வேறு யாரையும் அவர்கள் பெற்றெடுக்க மாட்டார்கள். இதற்குக் காரணம், அவர்கள் நீண்ட காலம் வாழ்ந்தும் அவர்களில் எவரும் இறைநம்பிக்கை கொள்ளவில்லை. அவர்களுடைய சந்ததியினரிடமும் நன்மை ஏதுமில்லை என்பதை அல்லாஹ் அவருக்கு (வஹி மூலம்) அறிவித்திருந்தான். அதனால்தான் அவர் இவ்வாறு பிரார்த்தனை செய்தார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾رَّبِّ</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">وَلِوَلِدَىَّ</span> <span class=\"quran-arabic-font text-success\">وَلِمَن</span> <span class=\"quran-arabic-font text-success\">دَخَلَ</span> <span class=\"quran-arabic-font text-success\">بَيْتِىَ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِناً﴿</span><br />\r\n(என் இறைவனே! எனக்கும், என் பெற்றோருக்கும், முஃமினாக என் வீட்டில் நுழைந்தவர்களுக்கும்...) இமாம் ளஹ்ஹாக் கூறினார்: \"அதாவது எனது பள்ளிவாசலில் (நுழைந்தவர்களுக்கும்).\" இருப்பினும், இங்கே வீடு என்பதற்குச் சொல்லப்பட்ட நேரடிப் பொருளே பொருத்தமானது. அதாவது அவரது குடும்பத்தாரில் இறைநம்பிக்கை கொண்டவர்கள். (இறைநம்பிக்கை கொள்ளாத) அவரது மகனும் மனைவியும் இதில் அடங்கமாட்டார்கள் என்று இப்னு ஜரீர் குறிப்பிடுகிறார்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلِلْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُؤْمِنَاتِ﴿</span><br />\r\n(மேலும் முஃமினான ஆண்களுக்கும், முஃமினான பெண்களுக்கும்) இது வாழும் மற்றும் மரணித்த இறைநம்பிக்கையாளர்கள் அனைவரையும் உள்ளடக்கும் பொதுவான பிரார்த்தனையாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَزِدِ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">تَبَارًا﴿</span><br />\r\n(மேலும் அநியாயக்காரர்களுக்கு அழிவைத் தவிர வேறு எதையும் நீ அதிகரிக்காதே!) ஸுத்தீ கூறினார்: \"அதாவது அழிவை.\" முஜாஹித் கூறினார்: \"நஷ்டத்தை.\" இவ்விரண்டு கருத்துக்களும் ஒன்றோடொன்று தொடர்புடையனவாகும்.<br />\r\n<br />\r\nஇத்துடன் ஸூரத்து நூஹ் (அலை) தஃப்ஸீர் நிறைவுற்றது. புகழும் அருளும் அல்லாஹ்வுக்கே உரியன.<br />\r\n<br />","text":"தம்முடைய சமூகத்தாரின் பதில் குறித்து நூஹ் (அலை) அவர்கள் தம் இறைவனிடம் முறையிடுதல்\n\r\n\n\r\nயாவற்றையும் அறிந்தவனும், எதனையும் தப்பவிடாதவனுமான அல்லாஹ்விடம், தான் விடுத்த தெளிவான மற்றும் முழுமையான அழைப்பைப் பற்றி முறையிட நூஹ் (அலை) அவர்கள் முற்பட்டதாக அல்லாஹ் கூறுகிறான். அவர்கள் சில நேரங்களில் நன்மாராயம் கூறியும், சில நேரங்களில் அச்சமூட்டி எச்சரித்தும் பல்வேறு வழிகளில் அவர்களை அழைத்தார்கள். ஆயினும், அவர்கள் அவருக்குக் கீழ்ப்படியாமல், அவரை எதிர்த்துப் பொய்யாக்கினர்; மேலும் உலகாதாயத்தில் மூழ்கியிருந்தவர்களையே பின்பற்றினர். அவர்கள் அல்லாஹ்வின் கட்டளையைப் புறக்கணித்தவர்களாகவும், செல்வங்கள் மற்றும் பிள்ளைச் செல்வங்கள் வழங்கப்பட்டவர்களாகவும் இருந்தனர். எனினும், இத்தகைய உலகியல் வசதிகள் அவர்களுக்குக் கண்ணியத்தையோ அல்லது அருளையோ தருவதற்காக வழங்கப்பட்டவை அல்ல; மாறாக அவை படிப்படியான தண்டனைக்கும் தற்காலிக அவகாசத்திற்குமே வழங்கப்பட்டன. எனவேதான் அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَاتَّبَعُواْ مَن لَّمْ يَزِدْهُ مَالُهُ وَوَلَدُهُ إِلاَّ خَسَاراً ﴿\n\r\n\n\r\n(மேலும், எவருடைய செல்வமும் பிள்ளைகளும் அவருக்கு நஷ்டத்தைத் தவிர வேறு எதையும் அதிகரிக்கவில்லையோ, அவரையே இவர்கள் பின்பற்றினார்கள்.)\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றான,\n\r\n﴾وَمَكَرُواْ مَكْراً كُبَّاراً   ﴿\n\r\n\n\r\n(மேலும் அவர்கள் ஒரு பெரும் சதித்திட்டத்தைத் தீட்டினார்கள்.) என்பதன் பொருள், தாங்கள் சத்தியத்தையும் நேர்வழியையுமே பின்பற்றுவதாகத் தங்களைப் பின்பற்றுபவர்களை நம்பவைத்து ஏமாற்றுவதற்காக, அவர்கள் ஒரு வஞ்சகமான சூழ்ச்சியைச் செய்தார்கள் என்பதாகும். இது மறுமை நாளில் அவர்கள் ஒருவருக்கொருவர் கூறிக்கொள்வதைப் போன்றதாகும்:\n\r\n﴾بَلْ مَكْرُ الَّيْلِ وَالنَّهَارِ إِذْ تَأْمُرُونَنَآ أَن نَّكْفُرَ بِاللَّهِ وَنَجْعَلَ لَهُ أَندَاداً  ﴿\n\r\n\n\r\n(இல்லை, மாறாக அது உங்களுடைய இரவும் பகலுமான சூழ்ச்சியாக இருந்தது: அல்லாஹ்வை நிராகரிக்குமாறும் அவனுக்கு இணைகளை ஏற்படுத்துமாறும் நீங்கள் எங்களுக்குக் கட்டளையிட்டபோது!) (34:33) இதனால்தான் அவன் (அல்லாஹ்) இங்கே கூறுகிறான்:\n\r\n\n\r\nநூஹ் (அலை) அவர்களின் சமூகத்தாரின் சிலைகளும் அவர்களுக்கு நேர்ந்தவையும்\n\r\n\n\r\n﴾وَمَكَرُواْ مَكْراً كُبَّاراً - وَقَالُواْ لاَ تَذَرُنَّ ءَالِهَتَكُمْ وَلاَ تَذَرُنَّ وَدّاً وَلاَ سُوَاعاً وَلاَ يَغُوثَ وَيَعُوقَ وَنَسْراً   ﴿\n\r\n\n\r\n(மேலும் அவர்கள் ஒரு பெரும் சதித்திட்டத்தைத் தீட்டினார்கள். மேலும் அவர்கள் கூறினார்கள்: 'உங்களுடைய கடவுள்களை நீங்கள் விட்டுவிடாதீர்கள்; வத், ஸுவா, யஃகூஸ், யஊக் மற்றும் நஸ்ர் ஆகிய சிலைகளையும் விட்டுவிடாதீர்கள்.') இவை அல்லாஹ்வையன்றி அவர்கள் வணங்கி வந்த சிலைகளின் பெயர்களாகும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக இமாம் புகாரி அவர்கள் பதிவு செய்துள்ளார்கள்: \"நூஹ் (அலை) அவர்களின் சமூகத்தாரிடம் இருந்த சிலைகள் பிற்காலத்தில் அரபிகளிடம் வந்து சேர்ந்தன. 'வத்' எனும் சிலை, தவ்மத் அல்-ஜந்தல் பகுதியில் வாழ்ந்த கல்ப் கோத்திரத்தாரின் சிலையாக மாறியது. 'ஸுவா' எனும் சிலை ஹுதைல் கோத்திரத்தாருக்கும், 'யஃகூஸ்' முராத் கோத்திரத்தாருக்கும் உரிய சிலையானது. பின்னர் ஸபா பகுதியில் உள்ள அல்-ஜுரூஃப் எனும் இடத்தில் பனீ ஃகுதைஃப் கோத்திரத்தாரும் அதை வணங்கினர். 'யஊக்' ஹம்தான் கோத்திரத்தாரின் சிலையாகவும், 'நஸ்ர்' ஹிம்யர் கோத்திரத்தில் உள்ள தூ கிலா குடும்பத்தாரின் சிலையாகவும் இருந்தது. இந்தச் சிலைகள் அனைத்தும் நூஹ் (அலை) அவர்களின் சமூகத்தில் வாழ்ந்த நல்ல மனிதர்களின் பெயர்களால் அழைக்கப்பட்டன. அவர்கள் இறந்தபோது, அவர்கள் கூடி அமர்ந்து வந்த இடங்களில் அவர்களின் நினைவாகச் சிலைகளை நிறுவுமாறும், அச்சிலைகளுக்கு அவர்களின் பெயர்களையே சூட்டுமாறும் ஷைத்தான் அந்த மக்களுக்குத் தூண்டினான். அவர்கள் அவ்வாறே செய்தனர். ஆனால், அந்த மக்கள் (அச்சிலைகளை உருவாக்கியவர்கள்) மரணித்து, அதுகுறித்த அறிவு மறைந்து போகும் வரை அச்சிலைகள் வணங்கப்படவில்லை. அதன் பின்னரே அவை வணங்கப்படலாயின.\" இது போன்ற ஒரு செய்தி இக்ரிமா, அத்-தஹ்ஹாக், கத்தாதா மற்றும் இப்னு இஸ்ஹாக் ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. அலி பின் அபீ தல்ஹா அவர்கள் இப்னு அப்பாஸ் (ரழி) வழியாக அறிவிக்கையில், \"இவை நூஹ் (அலை) அவர்களின் காலத்தில் வணங்கப்பட்ட சிலைகளாகும்\" என்று குறிப்பிட்டுள்ளார்கள். முஹம்மது பின் கைஸ் அவர்கள் யஃகூஸ், யஊக் மற்றும் நஸ்ர் ஆகிய சிலைகளைப் பற்றிக் கூறுகையில், \"இவர்கள் ஆதம் (அலை) மற்றும் நூஹ் (அலை) ஆகியோரின் காலத்திற்கு இடைப்பட்ட காலத்தில் வாழ்ந்த நல்ல மனிதர்களாவர். அவர்களைப் பின்பற்றும் ஆதரவாளர்கள் அவர்களுக்கு இருந்தனர். அவர்கள் இறந்தபோது, அவர்களைப் பின்பற்றியவர்கள்: 'அவர்களின் உருவங்களை நாம் அமைத்துக் கொண்டால், அவர்களைக் காணும்போது அது நமது வழிபாட்டு ஆர்வத்தை அதிகப்படுத்தும்' எனக் கூறி அவர்களின் உருவங்களைச் செய்தனர். பின்னர் அவர்கள் இறந்து, அவர்களுக்குப் பின் வந்த தலைமுறையினரிடம் இப்லீஸ் வந்து, 'உங்கள் முன்னோர்கள் இச்சிலைகளை வணங்கி வந்தனர்; அதன் காரணமாகவே அவர்களுக்கு மழையும் வழங்கப்பட்டது' என்று கூறினான். இவ்வாறு பிற்கால மக்கள் அவற்றை வணங்கத் தொடங்கினர்\" என்று இப்னு ஜரீர் பதிவு செய்துள்ளார்.\n\r\n\n\r\nதம்முடைய சமூகத்தினருக்கு எதிராகவும் தம்மை விசுவாசித்தவர்களுக்காகவும் நூஹ் (அலை) அவர்களின் பிரார்த்தனை\n\r\n\n\r\n﴾وَقَدْ أَضَلُّواْ كَثِيراً  ﴿\n\r\n\n\r\n(மேலும் நிச்சயமாக அவர்கள் பலரை வழிகெடுத்துவிட்டார்கள்.) அதாவது, அவர்கள் வணக்கத்திற்காக ஏற்படுத்திக்கொண்ட அச்சிலைகளின் மூலம் பெருவாரியான மக்களை வழிகேட்டில் தள்ளினார்கள். அந்தச் சிலைகளை வணங்கும் பழக்கம் இன்றுவரை பல தலைமுறைகளாக அரபிகளிடமும், அரபியர் அல்லாதவர்களிடமும், ஆதமுடைய மக்களிடமும் தொடர்ந்து வருகிறது. இப்ராஹீம் நபி (அலை) அவர்கள் தம் பிரார்த்தனையில் இதையே குறிப்பிட்டார்கள்:\n\r\n﴾وَاجْنُبْنِى وَبَنِىَّ أَن نَّعْبُدَ الأَصْنَامَ رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِّنَ النَّاسِ﴿\n\r\n\n\r\n(என்னையும் என் புதல்வர்களையும் சிலைகளை வணங்குவதிலிருந்து விலக்கி வைப்பாயாக. என் இறைவனே! நிச்சயமாக அவை மனிதர்களில் பலரை வழிகெடுத்துவிட்டன...) (14:35,36)\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَلاَ تَزِدِ الظَّـلِمِينَ إِلاَّ ضَلاَلاً  ﴿\n\r\n\n\r\n(அநியாயக்காரர்களுக்கு வழிகேட்டைத் தவிர வேறு எதையும் அதிகரிக்காதே.) இது நூஹ் (அலை) அவர்கள் தன் சமூகத்தாரின் கலகம், நிராகரிப்பு மற்றும் பிடிவாதம் காரணமாக அவர்களுக்கு எதிராகச் செய்த பிரார்த்தனையாகும். இது மூஸா (அலை) அவர்கள் ஃபிர்அவ்னுக்கும் அவனது தலைவர்களுக்கும் எதிராகச் செய்த பிரார்த்தனையைப் போன்றதேயாகும்:\n\r\n﴾رَبَّنَا اطْمِسْ عَلَى أَمْوَالِهِمْ وَاشْدُدْ عَلَى قُلُوبِهِمْ فَلاَ يُؤْمِنُواْ حَتَّى يَرَوُاْ الْعَذَابَ الْأَلِيمَ﴿\n\r\n\n\r\n(எங்கள் இறைவனே! அவர்களுடைய செல்வங்களை அழித்துவிடுவாயாக, அவர்களுடைய உள்ளங்களை இறுக்கிவிடுவாயாக; வேதனை தரும் நோவினையை அவர்கள் காணும் வரை அவர்கள் விசுவாசம் கொள்ள மாட்டார்கள்.) (10:88)\n\r\n\n\r\nநிச்சயமாக, அல்லாஹ் இந்த இரண்டு நபிமார்களின் பிரார்த்தனையை ஏற்றுக்கொண்டான். அவர்கள் கொண்டு வந்த சத்தியத்தை அவர்கள் நிராகரித்த காரணத்தினால் அல்லாஹ் அந்தச் சமூகத்தாரை மூழ்கடித்தான்.\n\r\n\n\r\n﴾مِّمَّا خَطِيئَاتِهِمْ أُغْرِقُوا فَأُدْخِلُوا نَارًا فَلَمْ يَجِدُوا لَهُم مِّن دُونِ اللَّهِ أَنصَارًا - وَقَالَ نُوحٌ رَّبِّ لاَ تَذَرْ عَلَى الْأَرْضِ مِنَ الْكَافِرِينَ دَيَّارًا - إِنَّكَ إِن تَذَرْهُمْ يُضِلُّوا عِبَادَكَ وَلاَ يَلِدُوا إِلاَّ فَاجِرًا كَفَّارًا - رَّبِّ اغْفِرْ لِى وَلِوَالِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَلاَ تَزِدِ الظَّالِمِينَ إِلاَّ تَبَارًا﴿\n\r\n\n\r\n(அவர்களுடைய பாவங்களின் காரணமாகவே அவர்கள் மூழ்கடிக்கப்பட்டு, நரகத்தில் புகுத்தப்பட்டார்கள்; அல்லாஹ்வையன்றி தங்களுக்கு உதவியாளர்கள் எவரையும் அவர்கள் காணவில்லை.\n\r\n\n\r\nமேலும் நூஹ் கூறினார்: \"என் இறைவனே! பூமியில் வசிப்போரில் காஃபிர்களில் எவரையும் நீ விட்டு வைக்காதே!\n\r\n\n\r\nநிச்சயமாக நீ அவர்களை விட்டுவைத்தால், அவர்கள் உன்னுடைய அடியார்களை வழிகெடுத்து விடுவார்கள்; மேலும் அவர்கள் பாவிகளையும், நன்றி கெட்டவர்களையுமன்றி (வேறு பிள்ளைகளைப்) பெற்றெடுக்க மாட்டார்கள்.\n\r\n\n\r\nஎன் இறைவனே! எனக்கும், என் பெற்றோருக்கும், முஃமினாக என் வீட்டில் நுழைந்தவர்களுக்கும், முஃமினான ஆண்களுக்கும், முஃமினான பெண்களுக்கும் நீ மன்னிப்பளிப்பாயாக! மேலும் அநியாயக்காரர்களுக்கு அழிவைத் தவிர வேறு எதையும் நீ அதிகரிக்காதே!\")\n\r\n\n\r\n**நூஹ் (அலை) அவர்கள் தம் இறைவனிடம் கேட்ட இறுதித் தீர்ப்பும், அது நிறைவேற்றப்பட்டதும்**\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n﴾مِّمَّا خَطِيئَاتِهِمْ أُغْرِقُوا﴿\n\r\n(அவர்களுடைய பாவங்களின் காரணமாகவே அவர்கள் மூழ்கடிக்கப்பட்டு...) அதாவது அவர்களுடைய அதிகமான பாவங்கள், அத்துமீறல்கள், அல்லாஹ்வை மறுத்தல் மற்றும் அவனது தூதரை எதிர்த்தல் ஆகியவற்றின் காரணமாக அவர்கள் வெள்ளப்பெருக்கின் மூலம் மூழ்கடிக்கப்பட்டார்கள்.\n\r\n﴾فَأُدْخِلُواْ نَاراً﴿\n\r\n(நரகத்தில் புகுத்தப்பட்டார்கள்) அதாவது அவர்கள் மூழ்கடிக்கப்பட்ட நிலையிலிருந்து (அடுத்து வரும் பர்ஸக் வாழ்வின்) நரக நெருப்பிற்கு மாற்றப்பட்டார்கள்.\n\r\n﴾فَلَمْ يَجِدُواْ لَهُمْ مِّن دُونِ اللَّهِ أَنصَاراً﴿\n\r\n(எனவே அல்லாஹ்வைத் தவிர தங்களுக்கு உதவுபவர் எவரையும் அவர்கள் காணவில்லை) அதாவது அல்லாஹ்வின் தண்டனையிலிருந்து அவர்களைக் காப்பாற்றவோ, தடுக்கவோ அல்லது பாதுகாக்கவோ கூடிய உதவியாளர், அடைக்கலம் தருபவர் அல்லது காப்பாளர் எவரும் அவர்களுக்குக் கிடைக்கவில்லை.\n\r\n\n\r\n﴾وَقَالَ نُوحٌ رَّبِّ لاَ تَذَرْ عَلَى الْأَرْضِ مِنَ الْكَافِرِينَ دَيَّارًا﴿\n\r\n(மேலும் நூஹ் கூறினார்: \"என் இறைவனே! பூமியில் வசிப்போரில் காஃபிர்களில் எவரையும் நீ விட்டு வைக்காதே!\") அதாவது பூமியின் மேற்பரப்பில் நடமாடக்கூடிய அவர்களில் ஒருவரைக்கூட விட்டுவிடாதே. அல்லாஹ் அவரது பிரார்த்தனையை ஏற்றுக்கொண்டான். அவர்களில் எஞ்சியிருந்த அனைவரையும் அவன் அழித்துவிட்டான்.\n\r\n\n\r\n﴾إِنَّكَ إِن تَذَرْهُمْ يُضِلُّواْ عِبَادَكَ﴿\n\r\n(நிச்சயமாக நீ அவர்களை விட்டுவைத்தால், அவர்கள் உன்னுடைய அடியார்களை வழிகெடுத்து விடுவார்கள்) அதாவது அவர்கள் வழிதவறியவர்களாகவும், மற்றவர்களை வழிகெடுப்பவர்களாகவும் இருப்பார்கள்.\n\r\n﴾وَلاَ يَلِدُواْ إِلاَّ فَاجِراً كَفَّاراً﴿\n\r\n(மேலும் அவர்கள் பாவிகளையும், நன்றி கெட்டவர்களையுமன்றி (வேறு பிள்ளைகளைப்) பெற்றெடுக்க மாட்டார்கள்) அதாவது தீயவர்களையும், (இறை)மறுப்பாளர்களையும் தவிர வேறு யாரையும் அவர்கள் பெற்றெடுக்க மாட்டார்கள். இதற்குக் காரணம், அவர்கள் நீண்ட காலம் வாழ்ந்தும் அவர்களில் எவரும் இறைநம்பிக்கை கொள்ளவில்லை. அவர்களுடைய சந்ததியினரிடமும் நன்மை ஏதுமில்லை என்பதை அல்லாஹ் அவருக்கு (வஹி மூலம்) அறிவித்திருந்தான். அதனால்தான் அவர் இவ்வாறு பிரார்த்தனை செய்தார்.\n\r\n\n\r\n﴾رَّبِّ اغْفِرْ لِى وَلِوَلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِناً﴿\n\r\n(என் இறைவனே! எனக்கும், என் பெற்றோருக்கும், முஃமினாக என் வீட்டில் நுழைந்தவர்களுக்கும்...) இமாம் ளஹ்ஹாக் கூறினார்: \"அதாவது எனது பள்ளிவாசலில் (நுழைந்தவர்களுக்கும்).\" இருப்பினும், இங்கே வீடு என்பதற்குச் சொல்லப்பட்ட நேரடிப் பொருளே பொருத்தமானது. அதாவது அவரது குடும்பத்தாரில் இறைநம்பிக்கை கொண்டவர்கள். (இறைநம்பிக்கை கொள்ளாத) அவரது மகனும் மனைவியும் இதில் அடங்கமாட்டார்கள் என்று இப்னு ஜரீர் குறிப்பிடுகிறார்.\n\r\n﴾وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴿\n\r\n(மேலும் முஃமினான ஆண்களுக்கும், முஃமினான பெண்களுக்கும்) இது வாழும் மற்றும் மரணித்த இறைநம்பிக்கையாளர்கள் அனைவரையும் உள்ளடக்கும் பொதுவான பிரார்த்தனையாகும்.\n\r\n\n\r\n﴾وَلاَ تَزِدِ الظَّالِمِينَ إِلاَّ تَبَارًا﴿\n\r\n(மேலும் அநியாயக்காரர்களுக்கு அழிவைத் தவிர வேறு எதையும் நீ அதிகரிக்காதே!) ஸுத்தீ கூறினார்: \"அதாவது அழிவை.\" முஜாஹித் கூறினார்: \"நஷ்டத்தை.\" இவ்விரண்டு கருத்துக்களும் ஒன்றோடொன்று தொடர்புடையனவாகும்.\n\r\n\n\r\nஇத்துடன் ஸூரத்து நூஹ் (அலை) தஃப்ஸீர் நிறைவுற்றது. புகழும் அருளும் அல்லாஹ்வுக்கே உரியன."},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=28\" class=\"link\">71:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:28 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=28\" class=\"link\">71:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:28 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=71&ayah=28\" class=\"link\">71:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 71:28 ஐ பார்க்கவும்"},"28":{"html":"<span class=\"quran-arabic-font text-success\">﴾مِّمَّا</span> <span class=\"quran-arabic-font text-success\">خَطِيئَاتِهِمْ﴿</span><br />\r\n(அவர்களுடைய பாவங்களின் காரணமாக) இது (<span class=\"quran-arabic-font text-success\">خَطَايَاهُمْ</span>) - (அவர்களுடைய தவறுகள்) என்றும் ஓதப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أُغْرِقُواْ﴿</span><br />\r\n(அவர்கள் மூழ்கடிக்கப்பட்டார்கள்,) அதாவது, அவர்களுடைய ஏராளமான பாவங்கள், கிளர்ச்சி, இறைமறுப்பில் பிடிவாதமாக இருந்தது மற்றும் தங்களின் தூதர்களுக்கு எதிராகச் செயல்பட்டது ஆகியவற்றின் காரணமாக அவர்கள் தண்டிக்கப்பட்டார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أُغْرِقُواْ</span> <span class=\"quran-arabic-font text-success\">فَأُدْخِلُواْ</span> <span class=\"quran-arabic-font text-success\">نَاراً﴿</span><br />\r\n(அவர்கள் மூழ்கடிக்கப்பட்டார்கள், பின்னர் நரக நெருப்பில் புகுத்தப்பட்டார்கள்.) அதாவது, அவர்கள் கடல் வெள்ளத்திலிருந்து அப்படியே நரக நெருப்பின் வெப்பத்திற்கு மாற்றப்படுவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَجِدُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَنصَاراً﴿</span><br />\r\n(அல்லாஹ்வைத் தவிர தங்களுக்கு உதவி செய்வோர் எவரையும் அவர்கள் காணவில்லை.) அதாவது, அல்லாஹ்வின் தண்டனையிலிருந்து தங்களைக் காக்கக்கூடிய உதவியாளரோ, துணைவரோ அல்லது இரட்சகரோ அவர்களுக்கு இருக்க மாட்டார்கள். இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لاَ</span> <span class=\"quran-arabic-font text-success\">عَاصِمَ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَمْرِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">رَّحِمَ﴿</span><br />\r\n(அல்லாஹ்வின் கட்டளையிலிருந்து (தண்டனையிலிருந்து) இன்று பாதுகாப்பவர் எவருமில்லை, அவன் அருள் புரிந்தவர்களைத் தவிர.) (<a href=\"qurandisp.php?sura=11&ayah=43\" class=\"link\">11:43</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَالَ</span> <span class=\"quran-arabic-font text-success\">نُوحٌ</span> <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَذَرْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرِينَ</span> <span class=\"quran-arabic-font text-success\">دَيَّاراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(மேலும் நூஹ் (அலை) கூறினார்கள்: \"என் இறைவனே! பூமியில் நிராகரிப்பாளர்களில் ஒருவரையும் (தய்யார்) எஞ்சவிடாதே!\") அதாவது, பூமியின் மேற்பரப்பில் அவர்களில் ஒருவரைக் கூட, ஒரு தனி நபரைக் கூட விட்டுவிடாதே. இது ஒரு கருத்தை ஆணித்தரமாக மறுத்துக் கூறும் முறையாகும். இப்னு அப்பாஸ் (ரழி) அவர்களும், அத்-தஹ்ஹாக் (ரழி) அவர்கள், \"தய்யார் என்றால் ஒருவர்\" என்று கூறினார்கள். அஸ்-ஸுத்தீ (ரழி) அவர்கள், \"தய்யார் என்பவர் வீட்டில் தங்குபவர்\" என்று கூறினார்கள். அல்லாஹ் அவரது பிரார்த்தனையை ஏற்றுக் கொண்டான். பூமியில் இருந்த நிராகரிப்பாளர்கள் அனைவரையும் அவன் அழித்தான். நூஹ் (அலை) அவர்களின் முதுகெலும்பிலிருந்து பிறந்த (சொந்த) மகனைக் கூட அல்லாஹ் அழித்தான். அவர் தன் தந்தை நூஹ் (அலை) அவர்களிடமிருந்து விலகிச் சென்றார். அவர் (நூஹ் (அலை) அவர்களின் மகன்) இவ்வாறு கூறினார்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾سَآوِى</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">جَبَلٍ</span> <span class=\"quran-arabic-font text-success\">يَعْصِمُنِى</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمَآءِ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">عَاصِمَ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَمْرِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">رَّحِمَ</span> <span class=\"quran-arabic-font text-success\">وَحَالَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمَا</span> <span class=\"quran-arabic-font text-success\">الْمَوْجُ</span> <span class=\"quran-arabic-font text-success\">فَكَانَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُغْرَقِينَ﴿</span><br />\r\n(\"நான் ஒரு மலையிடம் தஞ்சம் புகுவேன், அது என்னைத் தண்ணீரிலிருந்து காப்பாற்றும்\" (என்று மகன் கூறினான்). அதற்கு நூஹ் (அலை) அவர்கள், \"அல்லாஹ்வின் கட்டளையிலிருந்து இன்று பாதுகாப்பவர் எவருமில்லை, அவன் அருள் புரிந்தவர்களைத் தவிர\" என்று கூறினார்கள். (அப்போது) அவர்களுக்கு இடையே அலை குறுக்கிட்டது; அதனால் அவர் மூழ்கடிக்கப்பட்டவர்களில் ஒருவராகிவிட்டார்.) (<a href=\"qurandisp.php?sura=11&ayah=43\" class=\"link\">11:43</a>)<br />\r\n<br />\r\nநூஹ் (அலை) அவர்களுடன் ஈமான் கொண்டு கப்பலில் இருந்தவர்களை அல்லாஹ் காப்பாற்றினான். நூஹ் (அலை) அவர்கள் தன்னுடன் ஏற்றிக் கொள்ளுமாறு அல்லாஹ் கட்டளையிட்டவர்கள் இவர்களே ஆவர். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">تَذَرْهُمْ</span> <span class=\"quran-arabic-font text-success\">يُضِلُّواْ</span> <span class=\"quran-arabic-font text-success\">عِبَادَكَ﴿</span><br />\r\n(நிச்சயமாக நீ அவர்களை விட்டு வைத்தால், அவர்கள் உன்னுடைய அடியார்களை வழிதவறச் செய்வார்கள்,) அதாவது, 'அவர்களில் ஒருவரை நீ விட்டு வைத்தாலும், அவர்கள் உன்னுடைய அடியார்களை வழிதவறச் செய்வார்கள்.' இது அவர்களுக்குப் பின் அல்லாஹ் படைக்கவிருப்பவர்களைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَلِدُواْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فَاجِراً</span> <span class=\"quran-arabic-font text-success\">كَفَّاراً﴿</span><br />\r\n(மேலும் அவர்கள் பாவியான, பெரும் நிராகரிப்பாளர்களைத் தவிர வேறு எவரையும் பெற்றெடுக்க மாட்டார்கள்.) அதாவது, செயல்களில் தீயவர்களாகவும், உள்ளங்களில் இறைமறுப்பாளர்களாகவும் இருப்பார்கள். நூஹ் (அலை) அவர்கள் தொள்ளாயிரத்து ஐம்பது ஆண்டுகள் அவர்களிடையே தங்கியிருந்ததால், அவர்களைப் பற்றி நன்கு அறிந்திருந்ததன் காரணமாகவே இவ்வாறு கூறினார்கள். பின்னர் அவர் (நூஹ் (அலை)) இவ்வாறு பிரார்த்தித்தார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾رَّبِّ</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">وَلِوَالِدَيَّ</span> <span class=\"quran-arabic-font text-success\">وَلِمَن</span> <span class=\"quran-arabic-font text-success\">دَخَلَ</span> <span class=\"quran-arabic-font text-success\">بَيْتِىَ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِناً﴿</span><br />\r\n(என் இறைவனே! என்னையும், எனது பெற்றோரையும், நம்பிக்கையாளராக எனது வீட்டிற்குள் நுழைபவரையும் மன்னிப்பாயாக.) இதன் பொருள் 'எனது மஸ்ஜித்' என்று அத்-தஹ்ஹாக் (ரழி) அவர்கள் கூறினார்கள். இருப்பினும், இந்த வசனத்தை அதன் நேரடிப் பொருளில் புரிந்துகொள்வதில் தவறில்லை. அதாவது, விசுவாசியாகத் தன் வீட்டிற்குள் நுழைந்த ஒவ்வொருவருக்காகவும் நூஹ் (அலை) அவர்கள் பிரார்த்தனை செய்தார்கள். பின்னர் அவர் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلِلْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُؤْمِنَاتِ﴿</span><br />\r\n(மேலும் முஃமினான (நம்பிக்கை கொண்ட) ஆண்களையும் பெண்களையும் (மன்னிப்பாயாக).) விசுவாசம் கொண்ட அனைத்து ஆண்கள் மற்றும் பெண்களுக்காகவும் அவர் பிரார்த்தனை செய்தார்கள். இதில் உயிருடன் இருப்பவர்களும், மரணித்தவர்களும் அடங்குவர். இதன் காரணமாகவே, நூஹ் (அலை) அவர்களின் முன்மாதிரியைப் பின்பற்றி இவ்வாறே பிரார்த்திப்பது சிறந்தது என்று கருதப்படுகிறது. இவ்வாறான பிரார்த்தனைகள் பல நபிமொழிகளிலும் மார்க்க ரீதியாக அங்கீகரிக்கப்பட்ட துஆக்களிலும் இடம்பெற்றுள்ளன. உதாரணமாக, உபாதா பின் அஸ்-ஸாமித் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்: \"யார் முஃமினான ஆண், பெண்களுக்காகப் பாவமன்னிப்புக் கோருகிறாரோ, அவருக்கு ஒவ்வொரு முஃமினான ஆண், பெண்ணின் எண்ணிக்கைக்கு ஏற்ப ஒரு நன்மையை அல்லாஹ் பதிவு செய்கிறான்.\" பின்னர் அவர் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَزِدِ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">تَبَاراً﴿</span><br />\r\n(மேலும், அநீதியாளர்களுக்கு அழிவைத் தவிர வேறெதையும் அதிகப்படுத்தாதே!) இதற்கு \"அழிவைத் தவிர\" என்று அஸ்-ஸுத்தீ (ரழி) அவர்களும், \"நஷ்டத்தைத் தவிர\" என்று முஜாஹித் (ரழி) அவர்களும் விளக்கம் அளித்துள்ளனர். இது இவ்வுலகிற்கும் மறுமைக்கும் பொருந்தும்.<br />\r\n<br />\r\nஇத்துடன் ஸூரத்து நூஹ்-வின் தஃப்ஸீர் நிறைவுற்றது. அனைத்துப் புகழும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />","text":"﴾مِّمَّا خَطِيئَاتِهِمْ﴿\n\r\n(அவர்களுடைய பாவங்களின் காரணமாக) இது (خَطَايَاهُمْ) - (அவர்களுடைய தவறுகள்) என்றும் ஓதப்பட்டுள்ளது.\n\r\n\n\r\n﴾أُغْرِقُواْ﴿\n\r\n(அவர்கள் மூழ்கடிக்கப்பட்டார்கள்,) அதாவது, அவர்களுடைய ஏராளமான பாவங்கள், கிளர்ச்சி, இறைமறுப்பில் பிடிவாதமாக இருந்தது மற்றும் தங்களின் தூதர்களுக்கு எதிராகச் செயல்பட்டது ஆகியவற்றின் காரணமாக அவர்கள் தண்டிக்கப்பட்டார்கள்.\n\r\n\n\r\n﴾أُغْرِقُواْ فَأُدْخِلُواْ نَاراً﴿\n\r\n(அவர்கள் மூழ்கடிக்கப்பட்டார்கள், பின்னர் நரக நெருப்பில் புகுத்தப்பட்டார்கள்.) அதாவது, அவர்கள் கடல் வெள்ளத்திலிருந்து அப்படியே நரக நெருப்பின் வெப்பத்திற்கு மாற்றப்படுவார்கள்.\n\r\n\n\r\n﴾فَلَمْ يَجِدُواْ لَهُمْ مِّن دُونِ اللَّهِ أَنصَاراً﴿\n\r\n(அல்லாஹ்வைத் தவிர தங்களுக்கு உதவி செய்வோர் எவரையும் அவர்கள் காணவில்லை.) அதாவது, அல்லாஹ்வின் தண்டனையிலிருந்து தங்களைக் காக்கக்கூடிய உதவியாளரோ, துணைவரோ அல்லது இரட்சகரோ அவர்களுக்கு இருக்க மாட்டார்கள். இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\n﴾لاَ عَاصِمَ الْيَوْمَ مِنْ أَمْرِ اللَّهِ إِلاَّ مَن رَّحِمَ﴿\n\r\n(அல்லாஹ்வின் கட்டளையிலிருந்து (தண்டனையிலிருந்து) இன்று பாதுகாப்பவர் எவருமில்லை, அவன் அருள் புரிந்தவர்களைத் தவிர.) (11:43)\n\r\n\n\r\n﴾وَقَالَ نُوحٌ رَّبِّ لاَ تَذَرْ عَلَى الْأَرْضِ مِنَ الْكَافِرِينَ دَيَّاراً ﴿\n\r\n(மேலும் நூஹ் (அலை) கூறினார்கள்: \"என் இறைவனே! பூமியில் நிராகரிப்பாளர்களில் ஒருவரையும் (தய்யார்) எஞ்சவிடாதே!\") அதாவது, பூமியின் மேற்பரப்பில் அவர்களில் ஒருவரைக் கூட, ஒரு தனி நபரைக் கூட விட்டுவிடாதே. இது ஒரு கருத்தை ஆணித்தரமாக மறுத்துக் கூறும் முறையாகும். இப்னு அப்பாஸ் (ரழி) அவர்களும், அத்-தஹ்ஹாக் (ரழி) அவர்கள், \"தய்யார் என்றால் ஒருவர்\" என்று கூறினார்கள். அஸ்-ஸுத்தீ (ரழி) அவர்கள், \"தய்யார் என்பவர் வீட்டில் தங்குபவர்\" என்று கூறினார்கள். அல்லாஹ் அவரது பிரார்த்தனையை ஏற்றுக் கொண்டான். பூமியில் இருந்த நிராகரிப்பாளர்கள் அனைவரையும் அவன் அழித்தான். நூஹ் (அலை) அவர்களின் முதுகெலும்பிலிருந்து பிறந்த (சொந்த) மகனைக் கூட அல்லாஹ் அழித்தான். அவர் தன் தந்தை நூஹ் (அலை) அவர்களிடமிருந்து விலகிச் சென்றார். அவர் (நூஹ் (அலை) அவர்களின் மகன்) இவ்வாறு கூறினார்:\n\r\n\n\r\n﴾سَآوِى إِلَى جَبَلٍ يَعْصِمُنِى مِنَ الْمَآءِ قَالَ لاَ عَاصِمَ الْيَوْمَ مِنْ أَمْرِ اللَّهِ إِلاَّ مَن رَّحِمَ وَحَالَ بَيْنَهُمَا الْمَوْجُ فَكَانَ مِنَ الْمُغْرَقِينَ﴿\n\r\n(\"நான் ஒரு மலையிடம் தஞ்சம் புகுவேன், அது என்னைத் தண்ணீரிலிருந்து காப்பாற்றும்\" (என்று மகன் கூறினான்). அதற்கு நூஹ் (அலை) அவர்கள், \"அல்லாஹ்வின் கட்டளையிலிருந்து இன்று பாதுகாப்பவர் எவருமில்லை, அவன் அருள் புரிந்தவர்களைத் தவிர\" என்று கூறினார்கள். (அப்போது) அவர்களுக்கு இடையே அலை குறுக்கிட்டது; அதனால் அவர் மூழ்கடிக்கப்பட்டவர்களில் ஒருவராகிவிட்டார்.) (11:43)\n\r\n\n\r\nநூஹ் (அலை) அவர்களுடன் ஈமான் கொண்டு கப்பலில் இருந்தவர்களை அல்லாஹ் காப்பாற்றினான். நூஹ் (அலை) அவர்கள் தன்னுடன் ஏற்றிக் கொள்ளுமாறு அல்லாஹ் கட்டளையிட்டவர்கள் இவர்களே ஆவர். அல்லாஹ் கூறினான்:\n\r\n\n\r\n﴾إِنَّكَ إِن تَذَرْهُمْ يُضِلُّواْ عِبَادَكَ﴿\n\r\n(நிச்சயமாக நீ அவர்களை விட்டு வைத்தால், அவர்கள் உன்னுடைய அடியார்களை வழிதவறச் செய்வார்கள்,) அதாவது, 'அவர்களில் ஒருவரை நீ விட்டு வைத்தாலும், அவர்கள் உன்னுடைய அடியார்களை வழிதவறச் செய்வார்கள்.' இது அவர்களுக்குப் பின் அல்லாஹ் படைக்கவிருப்பவர்களைக் குறிக்கிறது.\n\r\n\n\r\n﴾وَلاَ يَلِدُواْ إِلاَّ فَاجِراً كَفَّاراً﴿\n\r\n(மேலும் அவர்கள் பாவியான, பெரும் நிராகரிப்பாளர்களைத் தவிர வேறு எவரையும் பெற்றெடுக்க மாட்டார்கள்.) அதாவது, செயல்களில் தீயவர்களாகவும், உள்ளங்களில் இறைமறுப்பாளர்களாகவும் இருப்பார்கள். நூஹ் (அலை) அவர்கள் தொள்ளாயிரத்து ஐம்பது ஆண்டுகள் அவர்களிடையே தங்கியிருந்ததால், அவர்களைப் பற்றி நன்கு அறிந்திருந்ததன் காரணமாகவே இவ்வாறு கூறினார்கள். பின்னர் அவர் (நூஹ் (அலை)) இவ்வாறு பிரார்த்தித்தார்கள்:\n\r\n\n\r\n﴾رَّبِّ اغْفِرْ لِى وَلِوَالِدَيَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِناً﴿\n\r\n(என் இறைவனே! என்னையும், எனது பெற்றோரையும், நம்பிக்கையாளராக எனது வீட்டிற்குள் நுழைபவரையும் மன்னிப்பாயாக.) இதன் பொருள் 'எனது மஸ்ஜித்' என்று அத்-தஹ்ஹாக் (ரழி) அவர்கள் கூறினார்கள். இருப்பினும், இந்த வசனத்தை அதன் நேரடிப் பொருளில் புரிந்துகொள்வதில் தவறில்லை. அதாவது, விசுவாசியாகத் தன் வீட்டிற்குள் நுழைந்த ஒவ்வொருவருக்காகவும் நூஹ் (அலை) அவர்கள் பிரார்த்தனை செய்தார்கள். பின்னர் அவர் கூறினார்கள்:\n\r\n\n\r\n﴾وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴿\n\r\n(மேலும் முஃமினான (நம்பிக்கை கொண்ட) ஆண்களையும் பெண்களையும் (மன்னிப்பாயாக).) விசுவாசம் கொண்ட அனைத்து ஆண்கள் மற்றும் பெண்களுக்காகவும் அவர் பிரார்த்தனை செய்தார்கள். இதில் உயிருடன் இருப்பவர்களும், மரணித்தவர்களும் அடங்குவர். இதன் காரணமாகவே, நூஹ் (அலை) அவர்களின் முன்மாதிரியைப் பின்பற்றி இவ்வாறே பிரார்த்திப்பது சிறந்தது என்று கருதப்படுகிறது. இவ்வாறான பிரார்த்தனைகள் பல நபிமொழிகளிலும் மார்க்க ரீதியாக அங்கீகரிக்கப்பட்ட துஆக்களிலும் இடம்பெற்றுள்ளன. உதாரணமாக, உபாதா பின் அஸ்-ஸாமித் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்: \"யார் முஃமினான ஆண், பெண்களுக்காகப் பாவமன்னிப்புக் கோருகிறாரோ, அவருக்கு ஒவ்வொரு முஃமினான ஆண், பெண்ணின் எண்ணிக்கைக்கு ஏற்ப ஒரு நன்மையை அல்லாஹ் பதிவு செய்கிறான்.\" பின்னர் அவர் கூறினார்கள்:\n\r\n\n\r\n﴾وَلاَ تَزِدِ الظَّالِمِينَ إِلاَّ تَبَاراً﴿\n\r\n(மேலும், அநீதியாளர்களுக்கு அழிவைத் தவிர வேறெதையும் அதிகப்படுத்தாதே!) இதற்கு \"அழிவைத் தவிர\" என்று அஸ்-ஸுத்தீ (ரழி) அவர்களும், \"நஷ்டத்தைத் தவிர\" என்று முஜாஹித் (ரழி) அவர்களும் விளக்கம் அளித்துள்ளனர். இது இவ்வுலகிற்கும் மறுமைக்கும் பொருந்தும்.\n\r\n\n\r\nஇத்துடன் ஸூரத்து நூஹ்-வின் தஃப்ஸீர் நிறைவுற்றது. அனைத்துப் புகழும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
